// Üretilen dosya: tool/ozgun/uret.py. Biyoloji · Bitki biyolojisi, ekoloji ve canlıların sınıflandırılması (orta).
const ozBiology4Orta = <(String, String, List<String>, String)>[
  ('Yaz ortasında öğle saatlerinde güneş altındaki bir bitkide su kaybı hızla artıyor. Bitkinin bu durumda su kaybını en kısa sürede azaltmasını sağlayan tepki hangisidir?', 'Stomalarını kapatması', ['Kökünü uzatması', 'Yeni ve geniş yapraklar açması', 'Çiçek oluşturması'], 'Bekçi hücreler turgorunu kaybedince stomalar kapanır; böylece terleme hızla azalır. Kök büyümesi gibi tepkiler çok daha yavaştır.'),
  ('Odunsu gövdelerin mantar tabakasında gaz alışverişini sağlayan, gevşek dizilmiş hücrelerden oluşan küçük kabartılara ne denir?', 'Lentisel', ['Stoma', 'Trikom', 'Hidatot'], 'Mantar doku gaz geçirmez; lentisellerdeki gevşek hücreler arasından iç dokular dış ortamla gaz alışverişi yapar.'),
  ('Kollenkima ile sklerenkima karşılaştırıldığında yalnız kollenkima için doğru olan ifade hangisidir?', 'Olgunlukta canlı hücrelerden oluşur', ['Lignin birikmiş kalın çeper taşır', 'Olgunlukta protoplastı ölmüştür', 'Lif ve taş hücrelerini içerir'], 'Kollenkima hücreleri canlıdır ve çeperleri köşelerde düzensiz kalınlaşmıştır; sklerenkima ise lignin birikmiş çeperli, çoğunlukla ölü hücrelerden oluşur.'),
  ('Kereviz sapının boyuna dizilmiş esnek ve sağlam şeritleri, genç ve büyümekte olan organlara esnek destek sağlayan hangi dokudan oluşur?', 'Kollenkima', ['Sklerenkima', 'Aerenkima', 'Mantar doku'], 'Kollenkima canlı ve esnek bir destek dokusudur; kereviz sapındaki şeritler tipik kollenkima örneğidir.'),
  ('Keten ve kenevir bitkilerinden dokuma ipliği elde edilmesi, bu bitkilerde hangi hücrelerin uzun ve dayanıklı olmasına dayanır?', 'Sklerenkima lifleri', ['Palizat hücreleri', 'Emici tüy hücreleri', 'Kollenkima hücreleri'], 'Keten ve kenevir lifleri, uzun ve lignin içeren kalın çeperli sklerenkima liflerinden oluşur.'),
  ('Ksilemin trake ve trakeitleri için aşağıdakilerden hangisi doğrudur?', 'Olgunlukta ölü ve içi boş hücrelerdir', ['Çekirdekli canlı hücrelerdir', 'Organik madde taşırlar', 'Çeperlerinde lignin bulunmaz'], 'Trake ve trakeitler olgunlaştığında protoplastlarını kaybeder; lignin ile güçlenmiş çeperlerden oluşan boş borular su iletir.'),
  ('Trakeitler ile trakeler karşılaştırıldığında, trakelerin su iletimini daha hızlı yapmasının başlıca yapısal nedeni nedir?', 'Uç çeperleri tamamen ya da kısmen erimiştir', ['İçlerinde canlı sitoplazma bulunur', 'Çeperlerinde lignin yoktur', 'Kalbur plaklarıyla birbirine bağlanırlar'], 'Trake hücrelerinin uç uca gelen çeperleri erimiş olduğundan kesintisiz borular oluşur; trakeitlerde su geçitlerden dolaşarak geçer.'),
  ('Kökte suyun hücre çeperleri boyunca serbestçe ilerlemesini durdurup sitoplazmadan geçmeye zorlayan Caspary şeritleri hangi tabakada bulunur?', 'Endodermis', ['Epidermis', 'Kaliptra', 'Korteksin dış kısmı'], 'Endodermis hücrelerinin çeperlerindeki suberinli Caspary şeritleri apoplast yolunu keser; böylece kök mineral girişini seçici olarak denetler.'),
  ('Buğday ve mısırda ana kök kısa sürede gelişimini durdurur ve gövde tabanından çıkan çok sayıda ince kök toprağı sarar. Bu kök tipinin bitkiye en önemli katkısı nedir?', 'Toprağın üst katmanını sıkıca tutması', ['Derinlerdeki taban suyuna kolayca erişmesi', 'Fazla miktarda besin depolaması', 'Havadaki nemi doğrudan emmesi'], 'Monokotillerdeki saçak kökler yüzeye yakın geniş bir ağ oluşturur; toprağı tutarak erozyonu azaltır ve yüzey suyunu iyi emer.'),
  ('Monokotil ve dikotil gövdeler karşılaştırıldığında, monokotil gövdeler için doğru olan özellik hangisidir?', 'İletim demetleri dağınık dizilmiştir', ['Demetlerde kambiyum bulunur', 'Gövdede belirgin yıllık halkalar oluşur', 'Demetler halka şeklinde dizilir'], 'Monokotillerde iletim demetleri gövdede dağınıktır ve kambiyum içermez; dikotillerde demetler halka şeklinde dizilir ve kambiyum bulunur.'),
  ('Bir yapraktaki damarların paralel uzandığı ve yaprağın gövdeyi kın şeklinde sardığı gözleniyor. Bu bitki büyük olasılıkla hangi gruptadır?', 'Monokotil', ['Dikotil', 'Açık tohumlu', 'Eğrelti'], 'Paralel damarlanma ve kınlı yaprak tabanı buğday, mısır gibi monokotillerin tipik özelliğidir; dikotillerde ağsı damarlanma görülür.'),
  ('Bezelyenin yapraklarının bir kısmı ince, kıvrılan uzantılara dönüşmüştür. Bu değişmiş yaprakların bitkiye sağladığı yarar nedir?', 'Desteğe sarılarak tırmanma', ['Böcek yakalayıp sindirerek azot sağlama', 'Su depolama', 'Eşeysiz üreme'], 'Bezelyedeki sülükler (yaprak kökenli asma filizleri) desteklere dolanır ve bitkinin ışığa doğru tırmanmasını sağlar.'),
  ('Aşağıdaki koşullardan hangisi bir bitkide terleme hızını en çok artırır?', 'Sıcak, kuru ve rüzgârlı hava', ['Serin, nemli ve rüzgârsız durgun hava', 'Karanlık ve nemli ortam', 'Soğuk ve sisli hava'], 'Sıcaklık ve rüzgâr buharlaşmayı artırır, kuru hava yaprak ile ortam arasındaki nem farkını büyütür; bu koşullar terlemeyi en yüksek düzeye çıkarır.'),
  ('İlkbaharda yaprak açmadan önce bir ağaçta kökteki nişasta depoları çözülüp tomurcuklara taşınıyor. Bu dönemde \'kaynak\' ve \'havuz\' görevini sırasıyla hangi organlar üstlenir?', 'Kök kaynak, tomurcuk havuzdur', ['Tomurcuk kaynak, kök havuzdur', 'Yaprak kaynak, kök ise havuz olur', 'Çiçek kaynak, yaprak havuzdur'], 'Kaynak şekeri sağlayan, havuz ise kullanan ya da depolayan organdır. Yaprak yokken depolardan şeker sağlayan kök kaynak, büyüyen tomurcuk havuz olur.'),
  ('Ksilem ve floem taşınımı karşılaştırıldığında yalnız floem için doğru olan ifade hangisidir?', 'İletim her iki yöne de olabilir', ['Taşınım her zaman yalnız yukarı doğrudur', 'İletim hücreleri ölüdür', 'Temel itici güç terlemedir'], 'Floem kaynaktan havuza taşıdığı için yön, organların durumuna göre yukarı ya da aşağı olabilir; ksilemde ise taşınım kökten yapraklara doğrudur.'),
  ('Bir çiftçi buğday hasadından sonra aynı tarlaya fasulye ekmeyi planlıyor. Bu ekim nöbetinin toprağa sağlayacağı en önemli yarar hangisidir?', 'Toprağın azotça zenginleşmesi', ['Toprağın tuzluluğunun artması', 'Toprak pH\'sinin hızla düşmesi', 'Yabani otların tamamen yok olması'], 'Fasulye bir baklagildir; köklerindeki azot bağlayıcı bakteriler toprağa azot kazandırır ve sonraki ürün için gübre gereksinimini azaltır.'),
  ('Böcekçil bitkiler genellikle hangi tür ortamlarda yaşar ve böcek yakalamaları hangi eksikliği giderir?', 'Azotça fakir bataklıklarda; azot eksikliğini', ['Kurak çöllerde; su eksikliğini', 'Gölgeli sık ormanlarda; ışık eksikliğini', 'Tuzlu kıyılarda; sodyum eksikliğini'], 'Sinekkapan ve güneşgülü gibi böcekçil bitkiler azotça fakir, asidik bataklıklarda yaşar; yakaladıkları böcekleri sindirerek azot ve fosfor sağlar. Fotosentezi ise sürdürürler.'),
  ('Ananas ve birçok kaktüs gibi çöl ya da kurak ortam bitkilerinin kullandığı fotosentez yolunun adı nedir?', 'CAM yolu', ['C3 yolu', 'Kemosentez', 'Fotosolunum yolu'], 'Ananas, kaktüs ve damkoruğu gibi bitkiler kurak koşullara uyum olarak CAM (Kalın Yapraklılarda Asit Metabolizması) yolunu kullanır.'),
  ('Ham muzları olgun elmalarla birlikte kapalı bir torbaya koymak muzların daha hızlı olgunlaşmasını sağlar. Bunun nedeni nedir?', 'Olgun elmaların etilen salması', ['Elmaların oksijeni tüketmesi', 'Elmaların ortamdaki ışığı muzlara yansıtması', 'Elmaların suyu emmesi'], 'Olgunlaşan meyveler etilen gazı yayar; kapalı ortamda biriken etilen diğer meyvelerin olgunlaşmasını da hızlandırır.'),
  ('Bir bahçıvan çalının uç tomurcuğunu kestikten sonra yan dalların hızla büyüdüğünü görüyor. Bu sonucu en iyi hangi olay açıklar?', 'Uç baskınlığının ortadan kalkması', ['Etilen üretiminin durması', 'Fotoperiyodun değişmesi', 'Köklerde absisik asit birikmesi'], 'Uç tomurcuğun ürettiği oksin yan tomurcukların büyümesini baskılar. Uç kesilince oksin kaynağı kalkar ve yan tomurcuklar gelişir.'),
  ('Kesilmiş çiçek ve yaprakların daha uzun süre taze kalması ve yaprak yaşlanmasının gecikmesi en çok hangi hormonla ilişkilidir?', 'Sitokinin', ['Etilen', 'Absisik asit', 'Florigen'], 'Sitokininler hücre bölünmesini uyarır ve yaprak yaşlanmasını geciktirir; etilen ise yaşlanma ve dökülmeyi hızlandırır.'),
  ('Yere yatay olarak bırakılan bir fidenin birkaç gün sonra kökünün aşağıya, gövdesinin yukarıya kıvrıldığı görülür. Bu tepkiyi yönlendiren temel uyaran nedir?', 'Yer çekimi', ['Işığın rengi', 'Toprak sıcaklığı', 'Havadaki nem'], 'Gravitropizmada kök yer çekimi yönünde (pozitif), gövde ise ters yönde (negatif) büyür. Kök ucundaki nişasta tanecikleri yer çekimini algılamada rol oynar.'),
  ('Küstüm otu (Mimosa pudica) yapraklarına dokunulduğunda yaprakçıklar saniyeler içinde kapanır. Bu hareketin tropizmadan farkı nedir?', 'Yönü uyaranın geldiği yöne bağlı değildir', ['Büyüme ile kalıcı ve geri dönüşsüz biçimde gerçekleşir', 'Yalnız köklerde görülür', 'Hormon olmadan hiçbir hücrede olmaz'], 'Küstüm otunun hareketi bir nastidir (sismonasti); turgor değişimiyle oluşur, hızlıdır ve uyaranın yönünden bağımsızdır.'),
  ('Lale çiçeklerinin sıcak odada açılıp serin ortamda kapanması hangi hareket türüne örnektir?', 'Termonasti', ['Fototropizma', 'Gravitropizma', 'Kemotropizma'], 'Sıcaklık değişimine bağlı, yönsüz açılma ve kapanma hareketine termonasti denir; lale ve çiğdem bilinen örneklerdir.'),
  ('Kasımpatı bir kısa gün bitkisidir. Bir seracı yaz ortasında çiçeklenmeyi sağlamak istiyorsa hangi uygulamayı yapmalıdır?', 'Bitkileri her gün erken saatte karartmak', ['Geceleri bitkileri birkaç saat boyunca ışıklandırmak', 'Bitkilere fazla azot vermek', 'Seranın sıcaklığını düşürmek'], 'Yazın geceler kısadır; bitkileri erken karartarak gece süresi uzatılırsa kısa gün koşulu sağlanır ve kasımpatı çiçeklenir.'),
  ('Ispanak bir uzun gün bitkisidir ve gece kısa olduğunda çiçeğe kalkar. Yaprağı için yetiştirilen ıspanakta bu özellik üretici açısından neden sorun oluşturabilir?', 'Yazın erken çiçeklenip yaprak kalitesi düşer', ['Kışın soğukta hiç yaprak oluşturamaz ve kurur', 'Karanlıkta hızla kök çürümesi başlar', 'Kısa günde yaprakları dikene dönüşür'], 'Uzun günlerde ıspanak çiçek sapı oluşturur (tohuma kaçar); bu dönemde yapraklar sertleşir ve acılaşır, bu yüzden ilkbahar ve sonbaharda yetiştirilir.'),
  ('Bir çiçekte hem erkek organ hem de dişi organ birlikte bulunuyorsa bu çiçek nasıl adlandırılır?', 'Erdişi (hermafrodit) çiçek', ['Tek eşeyli çiçek', 'Kısır (eşey organsız) çiçek', 'Bir evcikli bitki'], 'İki eşey organını birlikte taşıyan çiçeklere erdişi denir; yalnız birini taşıyanlar tek eşeylidir.'),
  ('Kromozom sayısı 2n = 24 olan bir kapalı tohumlu bitkinin tohumundaki endosperm hücrelerinde kaç kromozom bulunur?', '36', ['24', '12', '48'], 'Endosperm, n kromozomlu sperm ile iki adet n kromozomlu kutup çekirdeğinin birleşmesinden oluşur: 3n = 3 × 12 = 36.'),
  ('Bir çiçeğin poleninin aynı türden başka bir bireyin çiçeğindeki tepeciğe taşınmasının, kendi tozlaşmaya göre başlıca evrimsel avantajı nedir?', 'Döllerde genetik çeşitliliğin artması', ['Polen üretiminin tamamen ve kalıcı olarak durması', 'Tohumların daha küçük olması', 'Meyve oluşumunun gereksizleşmesi'], 'Çapraz tozlaşma farklı bireylerin genlerini birleştirir; döllerde çeşitlilik artar ve çevre değişimlerine uyum şansı yükselir.'),
  ('Bir kapalı tohumlu bitkide 30 tohumlu bir meyve oluşmuştur. Bu meyvenin oluşması için en az kaç polen tanesinin çimlenmiş olması gerekir?', '30', ['15', '60', '90'], 'Her polen tanesi iki sperm taşır ve bir tohum taslağında çift döllenmeyi gerçekleştirir; 30 tohum için en az 30 polen gerekir.'),
  ('Elmanın yenen etli kısmı büyük ölçüde yumurtalıktan değil, çiçek tablasının gelişmesinden oluşur. Bu tür meyvelere ne ad verilir?', 'Yalancı meyve', ['Kuru meyve', 'Basit gerçek meyve', 'Toplu meyve'], 'Yumurtalık dışındaki çiçek kısımlarının da etli kısma katıldığı meyvelere yalancı meyve denir; elma ve çilek örnektir.'),
  ('Fasulye tohumu ikiye ayrıldığında besinin büyük ölçüde iki etli yapıda depolandığı görülür. Bu yapılar nedir?', 'Çenekler', ['Endosperm katmanları', 'Tohum kabuğunun iç katmanları', 'Kaliptra hücreleri'], 'Fasulye gibi dikotil tohumlarında endosperm gelişme sırasında tüketilir ve besin iki çenekte depolanır.'),
  ('Dulavratotu meyvelerinin üzerindeki kancalı dikenler meyvenin hayvan tüylerine yapışmasını sağlar. Bu özelliğin bitkiye yararı nedir?', 'Tohumların uzak yerlere yayılması', ['Tohumların hemen çimlenmesi', 'Meyvenin şiddetli rüzgâra dayanabilmesi', 'Tohumun böceklerden korunması'], 'Kancalı meyveler hayvanlara yapışarak taşınır; yavrular ana bitkiden uzakta yeni alanlara yayılır ve rekabet azalır.'),
  ('Kuşların etli meyveleri yiyip tohumları dışkılarıyla başka yerlere bırakması hem bitki hem kuş açısından değerlendirildiğinde nasıl bir ilişkidir?', 'Her iki taraf da yarar sağlar', ['Yalnız kuş zarar görür', 'Yalnız bitki zarar görür', 'Her iki taraf da zarar görür'], 'Kuş besin kazanır, bitki ise tohumlarını yayar; bu karşılıklı yararlı (mutualist) bir ilişkidir.'),
  ('Bazı tohumların çimlenmesini artırmak için tohumlar bir süre nemli ve soğuk ortamda bekletilir. Bu uygulamanın adı nedir?', 'Stratifikasyon', ['Vernalizasyon', 'Aşılama', 'Daldırma'], 'Stratifikasyon tohumların kışı geçirmiş gibi soğuk ve nemde bekletilmesidir; dormansiyi kırar. Vernalizasyon ise çiçeklenmeyle ilgilidir.'),
  ('Fasulye çimlenirken çenekleri toprak üstüne çıkarken mısırda çenek toprak altında kalır. Bu farkın kök nedeni hangisidir?', 'Çim gövdenin farklı bölgelerinin uzaması', ['Mısırın tohumsuz bitki olması', 'Fasulyenin hiçbir zaman çiçek açmaması', 'Mısırın embriyosunun bulunmaması'], 'Fasulyede çenek altı gövde (hipokotil) uzayarak çenekleri yukarı iter; mısırda çenek üstü bölge uzar ve çenek toprak altında kalır.'),
  ('Bir öğrenci çimlenmede ışığın gerekli olup olmadığını sınamak için iki kap fasulye hazırlıyor. Deneyin geçerli olması için iki kap arasında yalnız hangi değişken farklı olmalıdır?', 'Işık alıp almamaları', ['Tohum türü', 'Her gün verilen su miktarı', 'Ortam sıcaklığı'], 'Kontrollü deneyde yalnız bağımsız değişken değiştirilir; diğer tüm koşullar aynı tutulmalıdır.'),
  ('Bazı çok küçük tohumların çimlenmek için ışığa gereksinim duyması, bu tohumların toprağa nasıl ekilmesi gerektiğini gösterir?', 'Toprak yüzeyine ya da çok sığ ekilmeli', ['Toprağın çok derinine gömülmeli', 'Karanlık depoda bekletilip öyle ekilmeli', 'Suya batırılıp çürütülerek ekilmeli'], 'Işıkla çimlenen küçük tohumlar derine gömülürse ışık alamaz ve çimlenemez; küçük tohumların az besini de derinden yüzeye çıkmaya yetmez.'),
  ('Kuru tohumlar uzun yıllar canlı kalabilirken su alınca kısa sürede solunum hızı artar. Bunun nedeni nedir?', 'Su alımı enzim etkinliğini başlatır', ['Su tohuma ışık enerjisi taşır', 'Kuru tohumda hiç hücre yoktur', 'Su kabuğu çözerek embriyoyu öldürür'], 'Kuru tohumda metabolizma çok yavaştır; su alınca (imbibisyon) enzimler etkinleşir, depo besinler yıkılır ve solunum hızlanır.'),
  ('Tamamen aynı genetik yapıdaki muz bitkilerinden oluşan geniş bir plantasyonun en büyük riski hangisidir?', 'Bir hastalığın tüm bitkileri birden etkileyebilmesi', ['Bitkilerin çok hızlı evrimleşmesi', 'Meyvelerin aşırı tohum içermesi', 'Bitkilerin birbirini tozlaştıramaması nedeniyle kuruması'], 'Genetik çeşitlilik olmadığında bir patojene karşı dirençsiz olan tüm bireyler aynı anda zarar görür; 20. yüzyılda Gros Michel muzunun Panama hastalığıyla çöküşü bilinen bir örnektir.'),
  ('Karayosunlarında gördüğümüz yeşil, yaprakçıklı bitkicik hangi döle aittir ve kromozom durumu nedir?', 'Gametofit; haploit (n)', ['Sporofit; diploit (2n)', 'Gametofit; diploit (2n)', 'Sporofit; haploit (n)'], 'Karayosunlarında baskın döl gametofittir; sporofit gametofitin üzerinde gelişir ve beslenmek için ona bağımlıdır.'),
  ('Eğrelti otlarında baskın ve uzun ömürlü döl için hangisi doğrudur?', 'Yapraklı bitki sporofittir', ['Yapraklı bitki gametofittir', 'Sporofit gametofite bağımlıdır', 'Gametofit iletim dokusu taşır'], 'Eğreltilerde gördüğümüz yapraklı bitki sporofittir ve iletim dokusu taşır; gametofit (protallus) küçük, kalp biçimli ve kısa ömürlüdür.'),
  ('Eğrelti yapraklarının alt yüzeyinde görülen kahverengi kümelerin işlevi nedir?', 'Spor üretmek', ['Fotosentez yapmak', 'Su depolamak', 'Böcekleri sindirmek'], 'Bu kümeler sporangiyum topluluklarıdır (sorus); içlerinde mayozla haploit sporlar oluşur ve rüzgârla yayılır.'),
  ('Kapalı tohumlu bir bitkinin embriyo kesesindeki yumurta hücresi n = 7 kromozom içeriyorsa, aynı bitkinin yaprak hücrelerinde kaç kromozom bulunur?', '14', ['7', '21', '28'], 'Yaprak hücreleri sporofite aittir ve diploittir: 2n = 2 × 7 = 14. Yumurta gametofitte oluşan haploit hücredir.'),
  ('Aşağıdaki özelliklerden hangisi kurak ortamda yaşayan bir bitkinin su kaybını azaltmaya yönelik uyarlaması değildir?', 'Geniş ve ince yapraklar', ['Kalın kütikula tabakası', 'Çukurlara gömülü stomalar', 'Tüylü yaprak yüzeyi'], 'Geniş ve ince yapraklar buharlaşma yüzeyini artırır; kserofitlerde ise yapraklar küçük, kalın kütikulalı ve stomalar çukurlarda gömüktür.'),
  ('Tropik yağmur ormanlarında bazı orkideler ağaç dallarının üzerinde yaşar, ancak ağaçtan besin almaz. Bu bitkiler nasıl adlandırılır?', 'Epifit', ['Parazit', 'Saprofit', 'Halofit'], 'Epifitler başka bitkilerin üzerinde destek için yaşar; suyu yağmur ve nemden, ışığı yüksekten alır, konakçıya zarar vermez.'),
  ('Çam ve ladin gibi kozalaklı ağaçların iğne yaprakları soğuk ve kurak kışlara nasıl uyum sağlar?', 'Küçük yüzeyleri ve kalın kütikulaları su kaybını azaltır', ['Kışın tüm yapraklarını dökerek terlemeyi tamamen durdururlar', 'Yapraklarında hiç stoma bulunmaz', 'Yaprakları suyu doğrudan kardan emer'], 'İğne yaprakların yüzey/hacim oranı küçüktür, kütikulası kalındır ve stomaları gömüktür; böylece soğuk ve fizyolojik kuraklık dönemlerinde su kaybı azalır.'),
  ('Aşağıdaki ekolojik organizasyon basamaklarından hangisi küçükten büyüğe doğru sırayla verilmiştir?', 'Birey, popülasyon, komünite, ekosistem', ['Popülasyon, birey, ekosistem, komünite', 'Komünite, popülasyon, birey, biyosfer', 'Ekosistem, komünite, biyosfer, popülasyon'], 'Birey aynı türden diğer bireylerle popülasyonu, popülasyonlar komüniteyi, komünite cansız çevreyle ekosistemi oluşturur.'),
  ('Ekosistemlerde ölü organizmaları ve atıkları parçalayarak inorganik maddeleri yeniden toprağa kazandıran canlılar hangi grupta yer alır?', 'Ayrıştırıcılar', ['Üreticiler', 'Birincil tüketiciler', 'Etçil tüketiciler'], 'Bakteri ve mantarlar gibi ayrıştırıcılar organik maddeleri inorganik maddelere dönüştürerek madde döngülerini tamamlar.'),
  ('Derin okyanus tabanındaki sıcak su kaynaklarında güneş ışığı olmadan yaşayan topluluklarda üretici görevini hangi canlılar üstlenir?', 'Kemosentetik bakteriler', ['Fotosentetik algler', 'Otçul balıklar', 'Ölü maddeyle beslenen saprofit mantarlar'], 'Bu ortamda bakteriler hidrojen sülfür gibi inorganik maddelerin oksidasyonundan elde ettikleri enerjiyle organik madde üretir; buna kemosentez denir.'),
  ('Bir araştırmacı, \'Bir tarladaki toprak solucanları ekosistemin abiyotik bileşenidir, çünkü toprağın içinde yaşar\' diyor. Bu ifadenin değerlendirmesi hangisidir?', 'Yanlıştır; solucan canlı olduğu için biyotiktir', ['Doğrudur; toprakla ilgili her şey abiyotiktir', 'Doğrudur; solucanlar üretici olduğu için abiyotiktir', 'Yanlıştır; solucanlar yalnız su ekosisteminde biyotiktir'], 'Bir bileşenin biyotik ya da abiyotik oluşu yaşadığı yere değil, canlı olup olmadığına bağlıdır; solucan bir ayrıştırıcı-detritivor canlıdır.'),
  ('Bir besin ağında hem bitki hem de hayvan yiyerek birden fazla trofik düzeyde beslenen canlılara ne ad verilir?', 'Hepçil (omnivor)', ['Otçul (herbivor)', 'Ayrıştırıcı', 'Üretici (ototrof)'], 'Ayı ve insan gibi hepçiller hem üreticilerle hem de tüketicilerle beslenir; bu nedenle besin ağında birden fazla düzeyde yer alır.'),
  ('Bir besin zincirinde üreticilerin depoladığı enerji 50 000 kJ ise ve her düzeye yaklaşık %10 aktarılıyorsa, ikincil tüketicilere ulaşan enerji ne kadardır?', '500 kJ', ['5 000 kJ', '50 kJ', '5 kJ'], 'Birincil tüketiciye 50 000 × 0,1 = 5 000 kJ, ikincil tüketiciye 5 000 × 0,1 = 500 kJ aktarılır.'),
  ('Besin zincirlerinin genellikle 4–5 halkadan uzun olmamasının en iyi açıklaması hangisidir?', 'Üst düzeylere ulaşan enerji çok azalır', ['Üst düzey avcılar fotosentez yapamaz', 'Ayrıştırıcılar yalnız ilk halkada bulunur', 'Uzun zincirlerde madde döngüsü durur'], 'Her düzeyde enerjinin yaklaşık %90\'ı kaybolduğundan birkaç halkadan sonra kalan enerji yeni bir popülasyonu besleyemeyecek kadar azalır.'),
  ('Tek bir büyük meşe ağacında yaşayan binlerce tırtılın oluşturduğu sistemde sayı piramidi nasıl görünür?', 'Ters (tabanı dar) piramit', ['Düzgün (tabanı geniş) piramit', 'Dikdörtgen biçimli', 'Tümüyle simetrik altıgen'], 'Üretici olan tek ağacın üzerinde çok sayıda tırtıl bulunduğundan tabanda bir birey, üstte binlerce birey olur; sayı piramidi tersine döner.'),
  ('Bir çayırda üreticiler yılda 20 000 kJ/m² enerji depoluyor. Birincil tüketicilere 2 400, ikincil tüketicilere 180 kJ/m² enerji aktarılıyor. Birincil tüketiciden ikincil tüketiciye aktarım verimi yüzde kaçtır?', '%7,5', ['%12', '%0,9', '%10'], 'Aktarım verimi = 180 / 2 400 × 100 = %7,5. Üreticiden birincil tüketiciye verim ise 2 400 / 20 000 = %12\'dir.'),
  ('Aşağıdaki olaylardan hangisi atmosfere karbondioksit eklemez?', 'Deniz yosunlarının ışıkta CO2 bağlaması', ['Odunun ve kömürün sobada yanması', 'Hayvanların gece ve gündüz yaptığı solunum', 'Ölü yaprakların çürümesi'], 'Yosunların fotosentezi CO2 tüketir. Yanma, solunum ve mikrobiyal ayrışma ise CO2 açığa çıkarır.'),
  ('Geniş bir orman alanı yakılıp yerine taş ocağı açılırsa bölgenin karbon dengesi kısa vadede nasıl etkilenir?', 'Atmosfere salınan CO2 artar, bağlanan CO2 azalır', ['Atmosferdeki CO2 hızla azalır', 'Karbon döngüsü üzerinde hiç etki olmaz', 'Bölgede kalan bitkilerin fotosentezi hemen ikiye katlanır'], 'Yanma depolanmış karbonu CO2 olarak salar; ağaçların yok olmasıyla bölgenin fotosentezle CO2 bağlama kapasitesi de ortadan kalkar.'),
  ('Bir öğrenci \'Karbon döngüsünde karbon atomları yalnız atmosfer ile bitkiler arasında gidip gelir\' diyor. Bu görüş neden eksiktir?', 'Okyanuslar, kayaçlar ve fosil yakıtlar da büyük karbon depolarıdır', ['Karbon atomları döngüde hiç dolaşmaz', 'Karbon yalnız hayvanlarda bulunur, bitkiler ise karbonu hiç içermez', 'Bitkiler karbonu topraktan alır'], 'Karbonun büyük kısmı okyanuslarda çözünmüş hâlde ve tortul kayaçlarda (kireçtaşı) bulunur; fosil yakıtlar da uzun süreli bir depodur.'),
  ('Oksijensiz, suya doymuş topraklarda azotlu gübrelerin etkisinin azalması en çok hangi bakteri etkinliğiyle ilişkilidir?', 'Denitrifikasyonla nitratın azot gazına dönüşmesi', ['Nitrifikasyonla amonyağın nitrata dönüşmesi', 'Azot bağlamayla N2\'nin amonyağa dönüşmesi', 'Fotosentezle nitratın glikoz ve oksijene dönüştürülmesi'], 'Oksijensiz koşullarda denitrifikasyon bakterileri nitratı solunumda kullanır ve N2 gazı olarak atmosfere geri verir; böylece topraktaki azot kaybolur.'),
  ('Azot döngüsünde N2 gazını doğrudan kullanabilen ve organik bileşiklere katabilen canlıların ortak özelliği nedir?', 'Prokaryot olmaları', ['Ökaryot hayvan olmaları', 'Yalnız yeşil bitki olmaları', 'Mantar olmaları'], 'Nitrojenaz enzimi taşıyan azot bağlayıcı canlıların tamamı prokaryottur: Rhizobium, Azotobacter ve siyanobakteriler bunlara örnektir.'),
  ('Geniş bir tropik ormanın kesilmesi bölgenin su döngüsünü nasıl etkiler?', 'Terleme ve yağış azalır, yüzey akışı artar', ['Terleme artar, yağış iki katına çıkar', 'Yer altı suyu hızla artar ve toprak erozyonu tamamen durur', 'Su döngüsü hiç etkilenmez'], 'Ağaçlar terlemeyle atmosfere su verir ve yağışı besler; kökleri toprağı tutar. Kesildiklerinde yerel yağış azalır, yağmur suyu toprağa sızmadan akar ve erozyon artar.'),
  ('Deniz kuşlarının yoğun yaşadığı kıyı adalarında biriken guano (kuş dışkısı) tarihte gübre olarak çok değerli olmuştur. Bunun nedeni nedir?', 'Fosfor ve azotça çok zengin olması', ['Yalnız karbon içermesi', 'Toprağı tuzlu yaparak koruması', 'Bitkilerde fotosentezi gereksiz kılması'], 'Balıkla beslenen kuşların dışkısı denizdeki fosforu ve azotu karaya taşır; guano bu yüzden doğal bir fosfat ve azot gübresidir.'),
  ('Bir kapalı cam kavanozda ışık alan su bitkisi ve salyangoz birlikte uzun süre yaşayabiliyor. Bunun karbon ve oksijen açısından açıklaması nedir?', 'Bitki salyangozun CO2\'sini kullanıp oksijen verir', ['Salyangoz fotosentez yaparak bitkiyi besler', 'Kavanozdaki hava hiçbir canlı tarafından kullanılmaz', 'Bitki ve salyangoz aynı gazı üretir'], 'Bitki fotosentezle CO2 tüketir ve O2 üretir; salyangoz O2 ile solunum yapıp CO2 verir. Ayrıştırıcılarla birlikte gazlar ve maddeler kavanoz içinde döner, enerji ise ışıkla dışarıdan girer.'),
  ('Bir göldeki kurbağa popülasyonunda bir yılda 340 doğum, 210 ölüm, 25 göç ile gelme ve 45 göç ile gitme oluyor. Popülasyon bu yıl sonunda nasıl değişmiştir?', '110 birey artmıştır', ['130 birey artmıştır', '90 birey artmıştır', '110 birey azalmıştır'], 'Değişim = (doğum + gelen) − (ölüm + giden) = (340 + 25) − (210 + 45) = 365 − 255 = 110 birey artış.'),
  ('Doğal ortamda büyüyen bir popülasyonun bir süre sonra belirli bir büyüklükte dengelenmesi ve S biçimli eğri çizmesinin nedeni nedir?', 'Çevre direncinin büyümeyi sınırlaması', ['Bireylerin belirli bir sayıdan sonra üremeyi tamamen bırakması', 'Tüm avcıların ortadan kalkması', 'Kaynakların sonsuza dek artması'], 'Besin, alan, hastalık ve avcılık gibi çevre direnci etmenleri popülasyon büyüdükçe etkisini artırır; popülasyon taşıma kapasitesi çevresinde dengelenir.'),
  ('Her 30 dakikada bir bölünen bir bakteri türünden bir besi ortamına 50 bakteri konuyor. Ortamda hiçbir sınırlama olmadığı varsayılırsa 3 saat sonra kaç bakteri olur?', '3 200', ['1 600', '300', '6 400'], '3 saat = 6 bölünme; 50 × 2^6 = 50 × 64 = 3 200 bakteri.'),
  ('Aşağıdakilerden hangisi yoğunluğa bağlı bir sınırlayıcı etmen değildir?', 'Ani bir orman yangını', ['Besin için rekabet', 'Kalabalıkta yayılan bulaşıcı hastalıklar', 'Barınak için rekabet'], 'Yangın, sel ve don gibi doğal afetler popülasyonun yoğunluğundan bağımsız olarak bireyleri etkiler; rekabet ve hastalık ise yoğunluk arttıkça şiddetlenir.'),
  ('Bir ada geyik popülasyonu taşıma kapasitesini aşarak hızla arttıktan sonra çöküyor. Bu olayın en olası açıklaması hangisidir?', 'Aşırı otlama kaynakları tüketti', ['Taşıma kapasitesi sonsuza dek arttı', 'Geyikler fotosentez yapmaya başladı', 'Adaya yeni bitki türleri yayıldı'], 'Taşıma kapasitesi aşıldığında bitki örtüsü yenilenme hızından fazla tüketilir; besin kıtlığıyla açlık ve ölümler artar, popülasyon çöker.'),
  ('Bir popülasyonun yaş piramidinde tabandaki genç birey oranı çok geniş, üst yaş grupları dar ise bu popülasyon için en uygun yorum hangisidir?', 'Hızla büyüyen bir popülasyondur', ['Küçülmekte olan bir popülasyondur', 'Durgun bir popülasyondur', 'Yalnız yaşlı bireylerden oluşur'], 'Geniş taban üreme çağına girecek çok sayıda genç birey olduğunu gösterir; bu popülasyonun yakın gelecekte hızla büyüyeceğini işaret eder.'),
  ('Sivrisinekler ve birçok tek yıllık yabani ot, çok sayıda küçük döl üretir, yavru bakımı yapmaz ve kısa sürede olgunlaşır. Bu türler en iyi hangi ortamlarda başarılıdır?', 'Değişken ve yeni açılmış ortamlarda', ['Uzun süre hiç değişmeyen ortamlarda', 'Yalnız kutup buzullarında', 'Taşıma kapasitesinin tam dolu olduğu ortamlarda'], 'r stratejistler hızlı üreyerek boş ya da sık bozulan ortamları çabuk doldurur; yavruların çoğu ölse de çok sayıda döl türün sürmesini sağlar.'),
  ('Bir gölde 80 balık yakalanıp işaretleniyor ve göle geri bırakılıyor. Bir hafta sonra yakalanan 100 balığın 16\'sının işaretli olduğu görülüyor. İşaretle-yeniden yakala yöntemine göre gölde yaklaşık kaç balık vardır?', '500', ['1 280', '200', '800'], 'N = (ilk işaretlenen × ikinci yakalanan) / ikinci yakalamadaki işaretli = (80 × 100) / 16 = 500.'),
  ('Nesli tehlikedeki bir kartal türünü korumak isteyen bir ekip yalnız yetişkinlerin sayısını izliyor. Bu yöntemin en önemli eksikliği nedir?', 'Yavru üretimi ve yaş yapısı hakkında bilgi vermez', ['Kartalların uçmasını engeller', 'Popülasyonu yapay yolla ve doğrudan artırarak sonuçları bozar', 'Kartalların renklerini değiştirir'], 'Yetişkin sayısı sabit görünse bile yeni yavru yetişmiyorsa popülasyon yaşlanıp çökebilir; yaş yapısı ve üreme başarısı da izlenmelidir.'),
  ('Kene, köpeğin kanını emerek beslenir ve ona hastalık bulaştırabilir. Bu ilişkide kenenin konakçısını genellikle hemen öldürmemesinin evrimsel açıklaması nedir?', 'Konakçı yaşadıkça parazit besin bulmaya devam eder', ['Kene gerektiğinde bitki özsuyuyla da rahatça beslenebilir', 'Köpek keneye karşı hiç tepki vermez', 'Kene konakçıya yarar sağlar'], 'Parazitin besin kaynağı ve yaşam ortamı konakçıdır; konakçının hızla ölmesi parazitin de kaynağını yitirmesi demektir.'),
  ('Aynı göletteki iki kurbağa türünden biri gündüz, diğeri gece avlanıyor ve böylece aynı böceklerle beslenirken bir arada yaşayabiliyor. Bu durum neyi örnekler?', 'Zamansal niş ayrımını', ['Mutualizmi', 'Besin zincirinde biyolojik birikimi', 'Ekolojik piramidi'], 'Türler aynı kaynağı farklı zamanlarda kullanarak rekabeti azaltabilir; bu nişin zamansal boyutudur.'),
  ('Bir türün habitatı ile ekolojik nişi arasındaki fark en iyi hangi benzetmeyle anlatılır?', 'Habitat türün adresi, niş ise mesleğidir', ['Habitat türün mesleği, niş ise adresidir', 'Habitat ve niş aynı kavramın iki farklı adıdır', 'Niş yalnız türün rengidir'], 'Habitat türün yaşadığı yerdir; niş ise türün o ortamda ne yediğini, ne zaman etkin olduğunu, hangi koşullara dayandığını kapsayan işlevsel rolüdür.'),
  ('Yangın geçirmiş bir ormanda toprağın korunduğu durumda başlayan süksesyonun birincil süksesyondan daha hızlı ilerlemesinin nedeni nedir?', 'Toprak ve içindeki tohumlar yerinde kalmıştır', ['Yangın sonrası güneş ışığı gelmez', 'Yanmış alanda hiç ayrıştırıcı kalmaz, madde döngüsü durur', 'İkincil süksesyonda öncü tür bulunmaz'], 'İkincil süksesyonda toprak, tohum bankası ve kök parçaları korunduğundan bitki örtüsü yüzyıllar yerine on yıllar içinde yeniden gelişebilir.'),
  ('Terk edilmiş bir tarlada önce tek yıllık otların, sonra çok yıllık otların, ardından çalıların ve sonunda ağaçların yerleştiği gözleniyor. Bu süreç hangisidir?', 'İkincil süksesyon', ['Birincil süksesyon', 'Ötrofikasyon', 'Biyolojik birikim'], 'Tarlada toprak zaten bulunduğundan bu süreç ikincil süksesyondur; topluluklar belirli bir sırayla birbirinin yerini alır.'),
  ('Tropik yağmur ormanlarında tür çeşitliliği çok yüksek olmasına karşın toprakların genellikle besince fakir olmasının nedeni nedir?', 'Besinler hızla ayrışıp bitkilerce tüketilir ve yağışla yıkanır', ['Ormanlarda hiç ayrıştırıcı bulunmaz ve yaprak çöpü yüzyıllarca birikir', 'Yapraklar hiç dökülmez', 'Toprak yıl boyu donmuş durumdadır'], 'Sıcak ve nemli koşullarda ayrışma çok hızlıdır; açığa çıkan mineraller ya hızla bitkilerce alınır ya da bol yağışla yıkanır. Besinlerin çoğu canlı biyokütlede tutulur.'),
  ('Seyrek ağaçlı geniş otlaklardan oluşan, belirgin kurak ve yağışlı mevsimleri bulunan, zebra ve zürafa gibi büyük otçulların yaşadığı biyom hangisidir?', 'Savan', ['Tayga', 'Tundra', 'Maki'], 'Savanlar Afrika\'da yaygın tropik otlaklardır; kurak mevsim ve yangınlar ağaçların sık büyümesini engeller.'),
  ('Akdeniz kıyılarında sıcak-kurak yaz ve ılık-yağışlı kışların etkisiyle gelişen, kocayemiş, mersin ve sandal gibi sert yapraklı, her dem yeşil çalılardan oluşan bitki örtüsü hangisidir?', 'Maki', ['Tundra', 'Tayga', 'Savan'], 'Maki, Akdeniz ikliminin tipik bitki örtüsüdür; yaz kuraklığına uyum olarak yaprakları küçük, sert ve kalın kütikulalıdır.'),
  ('Yüksek bir dağın eteğinden zirvesine çıkıldığında bitki kuşaklarının, ekvatordan kutuplara gidildiğinde görülen biyomlara benzer bir sıra izlemesinin nedeni nedir?', 'Yükseklikle sıcaklığın düşmesi', ['Yükseklikle yağışın her zaman sıfıra inmesi', 'Yükseklikle güneş ışığının tamamen kesilmesi', 'Dağlarda toprağın hiç oluşmaması'], 'Yükseklik arttıkça sıcaklık düşer; bu nedenle dağlarda ormandan iğne yapraklı kuşağa ve en üstte tundraya benzeyen alpin çayırlara geçilir.'),
  ('Denizlerde üretkenliğin en yüksek olduğu bölgelerden biri kıyıya yakın sığ sulardır. Bunun başlıca nedeni hangisidir?', 'Hem ışık hem de karadan gelen besin bol', ['Su sıcaklığı yıl boyu donma noktasındadır', 'Bu bölgede hiç tüketici yoktur', 'Su tuzsuz ve tamamen durgundur'], 'Kıyı sularında ışık dibe kadar ulaşır ve nehirler karadan mineral taşır; bu nedenle fitoplankton ve deniz çayırları çok üretkendir.'),
  ('Durgun bir gölün ılıman bölgede ilkbahar ve sonbaharda alt üst olması (karışması) ekosistem için neden önemlidir?', 'Oksijen dibe, besinler yüzeye taşınır', ['Gölün tamamen donmasını sağlar', 'Göldeki tüm balıkları ve planktonları öldürür', 'Işığın dibe ulaşmasını engeller'], 'Mevsimsel karışımda yüzeydeki oksijenli su dibe iner, dipteki besince zengin su yüzeye çıkar; bu da üretkenliği artırır.'),
  ('Bir gölde suyun DDT derişimi çok düşükken balık yiyen kuşların dokularında çok yüksek DDT bulunuyor. Bunun en doğru açıklaması hangisidir?', 'DDT atılamadığından her düzeyde birikerek artmıştır', ['Kuşlar DDT\'yi kendileri üretmektedir', 'DDT yalnız kuşların içtiği suda bulunur, balıklarda hiç yoktur', 'Planktonlar DDT\'yi tamamen parçalar'], 'Zooplankton fitoplanktonu, balıklar zooplanktonu, kuşlar balığı yer; her basamakta yenen çok sayıdaki canlının DDT\'si tüketicide toplanır.'),
  ('Bir belediye göldeki ötrofikasyonu önlemek istiyor. Aşağıdaki önlemlerden hangisi sorunun kaynağına yöneliktir?', 'Göle akan atık suları arıtıp fosforu tutmak', ['Göle daha fazla gübre katmak', 'Göldeki tüm balıkları ve suda yaşayan canlıları avlamak', 'Gölü her yaz suyla seyreltmeden bırakmak'], 'Ötrofikasyonun kaynağı besin girdisidir; atık su arıtımı ve gübre kullanımının denetimi azot ve fosfor girişini azaltır.'),
  ('Denizlere atılan plastiklerin küçük parçalara ayrılarak oluşturduğu mikroplastiklerin ekosisteme en önemli zararı hangisidir?', 'Canlılarca yutulup besin zincirine girmesi', ['Suyun sıcaklığını kaynama noktasına çıkarması', 'Denizde fotosentezi artırması', 'Deniz suyunu tatlı suya çevirmesi'], 'Mikroplastikler plankton, midye ve balıklar tarafından yutulur; sindirim sorunlarına yol açar ve taşıdıkları kimyasallar besin zincirinde yukarı aktarılabilir.'),
  ('Aşağıdaki gazlardan hangisi sera gazı olarak sınıflandırılmaz?', 'Azot', ['Karbondioksit', 'Metan', 'Diazot monoksit'], 'Atmosferin yaklaşık %78\'ini oluşturan N2 kızılötesi ışınımı soğurmaz; CO2, CH4 ve N2O ise önemli sera gazlarıdır.'),
  ('Pirinç tarlaları, bataklıklar ve geviş getiren hayvanların sindirim sistemleri hangi sera gazının önemli doğal ve tarımsal kaynaklarıdır?', 'Metan', ['Ozon', 'Kükürt dioksit', 'Kloroflorokarbon'], 'Oksijensiz ortamlarda yaşayan metanojen arkeler metan üretir; bu arkeler bataklık, çeltik tarlası ve işkembe gibi ortamlarda bulunur.'),
  ('İklim değişikliğinin ekosistemlere etkileri arasında aşağıdakilerden hangisi beklenen bir sonuç değildir?', 'Tüm türlerin yaşam alanlarının genişlemesi', ['Bazı türlerin daha yükseğe ve kutuplara kayması', 'Çiçeklenme ve göç zamanlarının değişmesi', 'Mercan beyazlaşmasının artması'], 'Isınmayla türler serin bölgelere kayar ve mevsimsel olayların zamanlaması değişir; dar toleranslı birçok türün alanı ise küçülür, hepsinin alanı genişlemez.'),
  ('Bir termik santral soğutma suyunu çok ısınmış olarak nehre geri bırakıyor. Bu ısıl kirliliğin nehirdeki balıklar üzerindeki en olası etkisi nedir?', 'Çözünmüş oksijen azalır, balıklar strese girer', ['Su soğuyup donar, balıklar kış uykusuna yatar', 'Suyun tuzluluğu artar, deniz balıkları yerleşir', 'Işık dibe ulaşamaz, balıklar körleşir'], 'Isınan suda oksijenin çözünürlüğü düşer, balıkların metabolizması ve oksijen gereksinimi artar; soğuk su türleri bölgeden çekilir ya da ölür.'),
  ('Likenlerin hava kirliliğinin biyolojik göstergesi (biyoindikatör) olarak kullanılmasının nedeni nedir?', 'Kükürt dioksit gibi kirleticilere çok duyarlıdırlar', ['Kirli havada daha hızlı büyürler', 'Yalnız şehir merkezlerinde yaşarlar', 'Kirleticileri hemen parçalayıp tamamen zararsız hâle getirirler'], 'Likenler su ve mineralleri doğrudan havadan ve yağmurdan alır; kirleticileri biriktirir ve SO2\'ye karşı çok duyarlıdır. Kirli bölgelerde çeşitlilikleri hızla düşer.'),
  ('Van Gölü\'nün sodalı ve tuzlu suyunda yaşayan, her ilkbahar üremek için göle dökülen tatlı su akarsularına göç eden ve Türkiye\'ye özgü balık türü hangisidir?', 'İnci kefali', ['Alabalık', 'Sazan', 'Karadeniz hamsisi'], 'İnci kefali (Alburnus tarichi) Van Gölü havzasına endemiktir; ilkbaharda üremek için göle dökülen akarsulara göç eder.'),
  ('Türkiye\'nin bitki çeşitliliği ve endemik bitki oranı Avrupa ülkelerinin çoğuna göre yüksektir. Aşağıdakilerden hangisi bunun nedenlerinden biri değildir?', 'Ülkenin tamamının tek bir iklim tipine sahip olması', ['Üç farklı bitki coğrafyası bölgesinin kesişmesi', 'Engebeli ve dağlık bir yer şekline sahip olması', 'Buzul çağlarında birçok tür için sığınak alanı olması'], 'Türkiye Avrupa-Sibirya, Akdeniz ve İran-Turan bölgelerinin kesiştiği, iklim ve yükselti farklılıkları çok fazla olan bir ülkedir; tek bir iklim tipine sahip değildir.'),
  ('Muğla\'daki İztuzu (Dalyan) kumsalı başta olmak üzere Türkiye\'nin Akdeniz kıyılarındaki bazı kumsallarda yumurtlayan ve koruma altında olan deniz kaplumbağası türü hangisidir?', 'Caretta caretta', ['Galápagos kaplumbağası', 'Leopar kaplumbağası', 'Kınlı kaplumbağa'], 'Caretta caretta (iribaş deniz kaplumbağası) Dalyan İztuzu gibi kumsallarda yumurtlar; ışık kirliliği ve kumsal yapılaşması en büyük tehditlerdendir.'),
  ('Hint Okyanusu\'ndaki Mauritius adasında yaşayan dodo kuşunun 17. yüzyılda nesli tükenmiştir. Bu olayın en önemli nedenleri hangi seçenekte verilmiştir?', 'Avlanma ve adaya getirilen yabancı hayvanlar', ['Buzul çağı ve volkanik patlamalar', 'Asit yağmuru ve ozon incelmesi', 'Plastik kirliliği ve termik santrallerin ısıl kirliliği'], 'Uçamayan ve insandan korkmayan dodo, avlanma ile adaya getirilen domuz, maymun ve sıçanların yumurtaları yemesi sonucu kısa sürede yok olmuştur.'),
  ('Kızıldeniz kökenli aslan balığının son yıllarda Doğu Akdeniz ve Türkiye kıyılarında yaygınlaşması en çok hangi yolla açıklanır?', 'Süveyş Kanalı üzerinden göç', ['Kutuplardan akıntıyla taşınma', 'Karadeniz\'den Boğazlar yoluyla iniş', 'Atlantik\'ten Cebelitarık\'a kuşlarla taşınma'], 'Süveyş Kanalı Kızıldeniz ile Akdeniz\'i bağlar; birçok tür bu yolla Akdeniz\'e geçmiştir. Isınan deniz suyu da yerleşmelerini kolaylaştırmıştır.'),
  ('Avustralya\'ya 1935\'te şeker kamışı zararlılarıyla mücadele için getirilen şeker kamışı kurbağasının (Rhinella marina) yerli yırtıcılar için ciddi sorun hâline gelmesinin nedeni nedir?', 'Zehirli olduğu için onu yiyen yerli yırtıcıları öldürmesi', ['Yerli bitkilerle tozlaşma yapıp onların aşırı çoğalmasına yol açması', 'Yalnız şeker kamışı zararlılarını yemesi', 'Kuraklıkta hemen ölmesi'], 'Kurbağanın derisindeki zehir, bu türü tanımayan yerli yılan, kertenkele ve keselileri öldürmüştür; kurbağa hızla çoğalarak kıtada geniş alana yayılmıştır.'),
  ('Bir balıkçılık kooperatifi uzun vadede balık stoklarını korumak istiyor. En sürdürülebilir uygulama hangisidir?', 'Üreme döneminde av yasağı ve ağ gözü sınırı koymak', ['Yavru balıkları da avlamak', 'Her yıl av miktarını artırmak', 'Dip trolüyle tüm deniz tabanını düzenli olarak taramak'], 'Üreme döneminde avlanmamak ve küçük balıkları kaçıracak ağ gözü kullanmak popülasyonun yenilenmesine izin verir; dip trolü ise tabandaki yaşam alanlarını tahrip eder.'),
  ('Damla sulama yönteminin salma sulamaya göre çevresel üstünlüğü nedir?', 'Su tasarrufu sağlar ve toprak tuzlanmasını azaltır', ['Daha fazla su kullanarak verimi artırır', 'Topraktaki tüm mineralleri yıkar', 'Bitkilerin köklerini yüzeye çıkararak havalanmalarını sağlar'], 'Damla sulama suyu doğrudan kök bölgesine az miktarda verir; buharlaşma ve derine sızma kayıpları azalır, yüzeyde tuz birikimi önlenir.'),
  ('Bir tarım alanında tek tür bitkinin geniş alanlara ekilmesinin (monokültür) biyoçeşitlilik açısından en önemli sakıncası hangisidir?', 'Zararlı ve hastalıkların hızla yayılabilmesi', ['Toprağın azotça zenginleşmesi', 'Tozlayıcı böcek türlerinin sayısının ve çeşidinin artması', 'Yabani türlerin çoğalması'], 'Tek tip bitki zararlılar için sınırsız besin sunar ve genetik çeşitlilik düşük olduğundan bir hastalık tüm alana yayılabilir; yaşam alanı çeşitliliği de azalır.'),
  ('Antik Çağda Aristoteles\'in hayvanları \'kanlı\' ve \'kansız\' olarak gruplandırması ile modern sınıflandırma arasındaki temel fark nedir?', 'Modern sınıflandırma evrimsel akrabalığa dayanır', ['Modern sınıflandırma yalnız renge dayanır', 'Aristoteles DNA dizilerini karşılaştırmıştır', 'Modern sistemde hiçbir basamak ya da kategori kullanılmaz'], 'Eski yapay sınıflandırmalar birkaç belirgin dış özelliğe dayanırdı; doğal (filogenetik) sınıflandırma ise anatomi, embriyoloji ve DNA benzerliklerine bakarak ortak atadan gelişi esas alır.'),
  ('Yarasa, kuş ve kelebeğin \'uçanlar\' adlı tek bir grupta toplanması hangi tür sınıflandırmaya örnektir ve neden yanıltıcıdır?', 'Yapay sınıflandırma; uçma yetenekleri bağımsız olarak gelişmiştir', ['Doğal sınıflandırma; üçü aynı sınıftandır', 'Filogenetik sınıflandırma; üçü aynı ataya sahiptir', 'Moleküler sınıflandırma; DNA dizilerinin tamamı birbirinin aynısıdır'], 'Kanatlar bu gruplarda farklı kökenlerden gelişmiş analog yapılardır; tek bir benzer işleve dayanan gruplama evrimsel akrabalığı yansıtmaz.'),
  ('Taksonomik basamaklarda alemden türe doğru inildikçe aşağıdakilerden hangisi artar?', 'Bireyler arasındaki benzerlik', ['Basamaktaki tür sayısı', 'Basamaktaki birey çeşitliliği', 'Basamaktaki farklı cins ve tür sayısı'], 'Alt basamaklara inildikçe gruptaki tür sayısı azalır, ortak özellikler ve benzerlik ise artar.'),
  ('Kedi (Felis catus) ve aslan (Panthera leo) aynı familyada, köpek (Canis familiaris) ise aynı takımda ancak farklı familyadadır. Buna göre aşağıdaki çıkarımlardan hangisi kesinlikle doğrudur?', 'Kedi ve aslan aynı sınıftadır', ['Kedi ve köpek aynı cinstedir', 'Aslan ve köpek aynı familyadadır', 'Kedi ve aslan aynı cinstedir'], 'Aynı familyadaki canlılar o familyanın üst basamakları olan takım, sınıf, şube ve alemde de ortaktır. Cinsleri farklıdır (Felis ve Panthera).'),
  ('Felis catus (ev kedisi) ve Felis silvestris (yaban kedisi) adları birlikte değerlendirildiğinde hangi sonuç çıkarılabilir?', 'İki tür aynı cinstedir', ['İki canlı aynı türdür', 'İki tür farklı familyalardadır', 'İki canlı farklı alemlerdedir'], 'Bilimsel adın ilk kelimesi aynı olan türler aynı cinse aittir; tür sıfatları farklı olduğundan farklı türlerdir.'),
  ('Dişi at ile erkek eşeğin çiftleşmesinden doğan katır genellikle kısırdır. Bu bilgi at ve eşek için hangi sonucu destekler?', 'Farklı türlerdir', ['Aynı türün iki ırkıdır', 'Aynı bireyin iki evresidir', 'Aynı popülasyonun üyeleridir'], 'Melez döl kısır olduğundan at ve eşek arasında gen akışı sürmez; biyolojik tür tanımına göre ayrı türlerdir.'),
  ('İnsan, şempanze ve goril aynı takımda (Primatlar) yer alır. Bu üç türün ortak olarak sahip olduğu daha üst basamaklar hangi seçenekte doğru verilmiştir?', 'Sınıf, şube ve alem', ['Cins, tür ve familya', 'Yalnız tür', 'Cins ve tür'], 'Aynı takımdaki canlılar takımın üzerindeki tüm basamakları (sınıf: memeliler, şube: kordalılar, alem: hayvanlar) paylaşır.'),
  ('Arkeler bir zamanlar bakterilerle aynı grupta sınıflandırılıyordu. Ayrı bir domain olarak kabul edilmelerinin temel nedeni nedir?', 'Moleküler özelliklerinin bakterilerden çok farklı olması', ['Çekirdeklerinin çift katlı bir zarla çevrili olması ve mitokondri taşımaları', 'Çok hücreli olmaları', 'Fotosentez yapan kloroplast taşımaları'], 'Arkeler prokaryottur, ancak rRNA dizileri, zar lipitleri ve bazı gen ifade mekanizmaları bakterilerden belirgin biçimde farklıdır; bazı yönleriyle ökaryotlara daha yakındır.'),
  ('Bir mikrobiyolog, zarla çevrili çekirdeği olmayan, hücre çeperinde peptidoglikan bulunan tek hücreli bir canlı tanımlıyor. Bu canlı hangi domaindedir?', 'Bakteriler', ['Arkeler', 'Ökaryotlar', 'Protistler'], 'Çekirdeksiz yapı prokaryot olduğunu gösterir; peptidoglikan çeper ise bakterilere özgüdür, arkelerin çeperinde peptidoglikan yoktur.'),
  ('Yoğurt yapımında sütün pıhtılaşmasını sağlayan ve sütteki laktozu laktik aside dönüştüren canlılar hangileridir?', 'Laktik asit bakterileri', ['Maya mantarları', 'Siyanobakteriler', 'Metan üreten metanojen arkeler'], 'Lactobacillus ve Streptococcus thermophilus gibi bakteriler laktik asit fermantasyonuyla sütü asitleştirir; proteinler pıhtılaşarak yoğurt oluşur.'),
  ('Bazı bakterilerin olumsuz koşullarda oluşturduğu endosporların özelliği hangisidir?', 'Isı ve kuraklığa karşı çok dirençli dinlenme yapılarıdır', ['Bakterinin eşeyli üremede kullandığı haploit gamet hücreleridir', 'Fotosentez yapan organellerdir', 'Bakteriyi hızla hareket ettiren yapılardır'], 'Endosporlar kalın örtülü, metabolizması durmuş yapılardır; kaynamaya ve kurumaya dayanabilir, koşullar düzelince yeniden etkin bakteriye dönüşür.'),
  ('Soğuk algınlığı gibi viral bir hastalıkta antibiyotik kullanmanın neden işe yaramadığı en iyi nasıl açıklanır?', 'Antibiyotikler bakterilere özgü yapıları hedefler', ['Antibiyotikler yalnız mantarları öldürür', 'Virüsler antibiyotikleri sindirir', 'Viral hastalıklar ilaçsız ve kendiliğinden hiçbir zaman geçmez'], 'Antibiyotikler bakteri çeperi, bakteri ribozomu gibi hedeflere etki eder; virüslerde bu yapılar bulunmadığından etkisizdir.'),
  ('Kaynar kaplıcalarda, Lut Gölü\'nün çok tuzlu sularında ve derin deniz bacalarında da yaşayabilen, zar lipitleri ve rRNA dizileriyle bakterilerden ayrılan prokaryot grup hangisidir?', 'Arkeler', ['Siyanobakteriler', 'Gram pozitif bakteriler', 'Mikoplazmalar'], 'Birçok arke aşırı sıcak, tuzlu ya da asidik ortamlarda yaşayabilir; bu yüzden ekstremofil olarak da bilinirler. Ancak arkeler sıradan ortamlarda da yaygındır.'),
  ('Tuzcul (halofil) arkelerin bulunduğu tuz göllerinin bazen pembe-kırmızı renkte görünmesinin nedeni nedir?', 'Arkelerin taşıdığı kırmızımsı pigmentler', ['Gölün dibindeki demir yataklarının yüzeye çıkması', 'Suya karışan kanın rengi', 'Göldeki buzun ışığı kırması'], 'Halofil arkeler ve bazı algler karotenoit ve bakteriorodopsin gibi pigmentler içerir; yoğun çoğaldıklarında suyu pembe-kırmızı renge boyarlar.'),
  ('Bir öğrenci \'Bütün bakteriler hastalık yapar\' diyor. Aşağıdakilerden hangisi bu görüşü en güçlü biçimde çürütür?', 'Bağırsaktaki bakterilerin K vitamini üretmesi', ['Bazı bakterilerin tifoya yol açması', 'Bakterilerin uygun koşullarda ikiye bölünerek çok hızlı çoğalması', 'Bakterilerin çekirdeğinin olmaması'], 'Bağırsak florası K vitamini ve bazı B vitaminlerini üretir, zararlı mikropların yerleşmesini engeller; ayrıca birçok bakteri ayrıştırıcı ve azot bağlayıcıdır.'),
  ('Öglena (Euglena) ışıklı ortamda kloroplastlarıyla fotosentez yapar, karanlıkta ise çevreden organik madde alabilir. Bu özellik onu nasıl tanımlar?', 'Hem ototrof hem heterotrof beslenebilen bir protist', ['Yalnız kemosentez yapan bir arke', 'Kloroplastlı, çok hücreli bir kara bitkisi türü', 'Kloroplastı olmayan bir mantar'], 'Öglena koşullara göre beslenme biçimini değiştirebilir (miksotrof); bu durum protistlerin bitki ve hayvan arasında kesin bir yere konmasını zorlaştırmıştır.'),
  ('Terliksi hayvanın (Paramecium) hücresinde bulunan kontraktil (atım) kofulunun görevi nedir?', 'Hücreye osmozla giren fazla suyu dışarı atmak', ['Besinleri sindirmek', 'Işığı algılamak', 'Genetik bilgiyi saklayıp yavru hücrelere aktarmak'], 'Tatlı su hipotonik olduğundan hücreye sürekli su girer; kontraktil koful bu suyu dışarı pompalayarak hücrenin patlamasını önler.'),
  ('Kıyı sularında bazı dinoflagellatların aşırı çoğalmasıyla oluşan ve deniz ürünlerinde zehir birikmesine yol açabilen olaya halk arasında ne ad verilir?', 'Kırmızı gelgit', ['Ozon deliği', 'Asit yağmuru', 'Kutuplarda buzul erimesi'], 'Kırmızı gelgitte dinoflagellatlar suyu renklendirir; ürettikleri toksinler midyelerde birikerek insanlarda zehirlenmelere yol açabilir.'),
  ('Ekmek hamurunun kabarmasında maya mantarının rolü nedir?', 'Şekeri fermente ederek CO2 üretmek', ['Hamura oksijen eklemek', 'Nişastayı proteine çevirmek', 'Hamurdaki suyu buharlaştırarak hamuru kurutmak'], 'Maya (Saccharomyces cerevisiae) şekerleri etil alkol fermantasyonuyla parçalar; açığa çıkan CO2 kabarcıkları hamuru kabartır, alkol fırında buharlaşır.'),
  ('Mantarların ekosistemlerdeki en önemli rollerinden biri aşağıdakilerden hangisidir?', 'Ölü organik maddeyi ayrıştırarak mineralleri döngüye katmak', ['Atmosferdeki azotu doğrudan bağlamak', 'Güneş enerjisiyle besin üretmek', 'Okyanuslarda oksijenli fotosentezin büyük kısmını tek başına yürütmek'], 'Mantarlar, özellikle odundaki lignin ve selülozu parçalayabilen başlıca ayrıştırıcılardır; madde döngülerinde vazgeçilmezdir.'),
  ('Doğada toplanan yabani şapkalı mantarların tüketilmesi konusunda en doğru tutum hangisidir?', 'Uzmanca tanınmayan mantar yenmemelidir', ['Rengi parlak olmayan her mantar yenebilir', 'Pişirmek tüm zehirleri yok eder', 'Hayvanların yediği mantar insana zararsızdır'], 'Bazı zehirli mantarlar yenebilen türlere çok benzer ve zehirleri pişirmekle bozulmaz; halk arasındaki \'güvenli\' ölçütler güvenilir değildir.'),
  ('Atlet ayağı ve pamukçuk gibi mantar enfeksiyonlarının tedavisinin bakteri enfeksiyonlarına göre daha zor olmasının bir nedeni nedir?', 'Mantar hücrelerinin insan hücrelerine daha çok benzemesi', ['Mantarların prokaryot olması', 'Mantarların hiç hücre zarı taşımaması', 'Mantarların virüslerin içinde yaşayarak ilaçlardan korunması'], 'Mantarlar da ökaryottur; ilaçların insan hücresine zarar vermeden yalnız mantara etki edecek farklı hedef bulması daha zordur.'),
  ('Rokfor ve Camembert gibi peynirlerin özel tat ve görünüşünü kazanmasını sağlayan canlılar hangi gruptandır?', 'Penicillium cinsi küf mantarları', ['Siyanobakteriler', 'Amipler', 'Peynir sularında yaşayan metanojen arkeler'], 'Rokforda Penicillium roqueforti mavi damarları, Camembert\'de Penicillium camemberti beyaz kabuğu oluşturur.'),
  ('Turbalık bataklıklarda biriken ve kurutularak bahçecilikte toprak düzenleyici olarak kullanılan turbanın ana kaynağı hangi bitki grubudur?', 'Sfagnum (turba yosunu)', ['Eğrelti otları', 'Kozalaklı ağaçlar', 'Buğdaygiller (tahıllar)'], 'Sfagnum yosunları asidik ve oksijensiz bataklıklarda yavaş ayrışarak birikir ve turbayı oluşturur; turbalıklar büyük karbon depolarıdır.'),
  ('Eğrelti otlarını karayosunlarından ayıran en önemli evrimsel yenilik hangisidir?', 'İletim dokusu taşımaları', ['Tohum üretmeleri', 'Çiçek açmaları', 'Döllenmenin suya bağımlı olmaması'], 'Eğreltiler gerçek kök, gövde, yaprak ve iletim dokusuna sahip ilk büyük gruptur; ancak hâlâ tohumsuzdur ve döllenmeleri suya bağlıdır.'),
  ('Bir öğrenci eğrelti otlarının yalnız nemli ve gölgeli yerlerde bol bulunmasını açıklamak istiyor. En geçerli açıklama hangisidir?', 'Kamçılı spermlerin yumurtaya ulaşması için su gerekir', ['Eğreltiler doğrudan güneş ışığında hiçbir biçimde fotosentez yapamaz', 'Eğreltilerin kökleri yoktur', 'Eğreltiler yalnız böceklerle tozlaşır'], 'Eğreltilerde küçük gametofit üzerinde oluşan kamçılı spermler yumurtaya su filmi içinde yüzerek ulaşır; bu nedenle nemli ortamlara bağımlıdırlar.'),
  ('Monokotil ve dikotil bitkiler karşılaştırıldığında aşağıdaki özelliklerden hangisi dikotillere aittir?', 'Çiçek kısımlarının genellikle 4 ya da 5\'in katları olması', ['Tohumda tek çenek bulunması', 'Yapraklarda paralel damarlanma', 'Gövdede dağınık dizilmiş iletim demetleri ve kambiyumsuzluk'], 'Dikotillerde iki çenek, ağsı damarlanma, halka şeklinde demetler ve 4-5\'in katları çiçek parçaları görülür; tek çenek, paralel damar ve dağınık demet monokotil özellikleridir.'),
  ('Bir bitkinin tohumu ikiye ayrıldığında besinin büyük ölçüde endospermde depolandığı ve tek bir çenek bulunduğu görülüyor. Aynı bitkinin gövde kesitinde aşağıdakilerden hangisinin görülmesi beklenir?', 'Dağınık iletim demetleri', ['Belirgin yıllık halkalar', 'Halka şeklinde dizili demetler', 'Kalın mantar kambiyumu'], 'Tek çenek monokotil olduğunu gösterir; monokotil gövdesinde demetler dağınıktır ve kambiyum bulunmadığından yıllık halka oluşmaz.'),
  ('Kozalaklı ağaçların çoğunun rüzgârla tozlaşmasının, aynı türden bireylerin geniş ve sık ormanlar oluşturmasıyla ilişkisi nedir?', 'Sık topluluklarda rüzgârla taşınan polenin hedefe ulaşma şansı yüksektir', ['Rüzgâr kozalaklıların fotosentezini artırır', 'Sık ormanlarda hiç rüzgâr esmez', 'Kozalaklıların çiçekleri renkli olduğundan böcekler onlardan uzak durur ve tozlaşma olmaz'], 'Rüzgârla tozlaşma rastlantıya dayanır; aynı türden bireylerin yakın ve bol olması polenin bir dişi kozalağa ulaşma olasılığını artırır.'),
  ('At kuyruğu (Equisetum) bitkisinin gövdesinde silis birikmesi, geçmişte bu bitkinin hangi amaçla kullanılmasına yol açmıştır?', 'Kap kacak ovmak ve parlatmak', ['Ekmek mayası yapmak', 'Kumaş boyamak', 'Sıtma hastalığını tedavi etmek'], 'At kuyruğunun pürüzlü, silisli gövdesi eskiden metal kapları ovmak için kullanılır, bu nedenle İngilizcede \'scouring rush\' olarak da anılır.'),
  ('Mısır, pirinç ve buğday gibi tahıllar insanlığın temel besin kaynaklarıdır. Bu bitkiler hangi aileye ve gruba aittir?', 'Buğdaygiller; monokotiller', ['Baklagiller; dikotiller', 'Gülgiller; dikotiller', 'Çamgiller; açık tohumlu kozalaklılar'], 'Tahıllar buğdaygiller (Poaceae) familyasındadır ve tek çenekli (monokotil) kapalı tohumlulardır.'),
  ('Tenya gibi bağırsak parazitlerinde sindirim sistemi bulunmaz. Bu durum nasıl açıklanır?', 'Konakçının sindirdiği besinleri vücut yüzeyinden emerler', ['Vücutlarındaki kloroplastlarla fotosentez yaparak kendi besinlerini üretirler', 'Hiç enerji gereksinimleri yoktur', 'Besinlerini ağızla yutup çiğnerler'], 'Tenya konakçı bağırsağında zaten sindirilmiş besinlerin içinde yaşar; bu küçük molekülleri doğrudan vücut yüzeyinden emer.'),
  ('Ahtapot ve mürekkep balığının diğer yumuşakçalardan farklı olarak gelişmiş bir sinir sistemine ve gözlere sahip olması hangi yaşam biçimiyle ilişkilidir?', 'Hızlı hareket eden etkin avcılık', ['Kayaya yapışık süzerek beslenme', 'Toprak altında yaşama', 'Bitkilerin üzerinde yavaşça sürünerek otlama'], 'Kafadanbacaklılar etkin avcılardır; avı bulmak, kovalamak ve avcılardan kaçmak için gelişmiş beyin, gözler ve jet itkisiyle hareket yetenekleri evrimleşmiştir.'),
  ('Örümcek, akrep ve keneyi böceklerden ayıran özellik hangisidir?', 'Dört çift bacak taşımaları ve anten bulunmaması', ['Dış iskeletlerinin olmaması', 'Eklemli bacakların bulunmaması ve vücudun tek parça olması', 'Kanatlarının üç çift olması'], 'Örümceğimsilerde dört çift yürüme bacağı vardır, anten yoktur ve vücut genellikle iki bölümlüdür.'),
  ('Bir derenin canlı çeşitliliğini değerlendiren araştırmacılar taş altlarında bol miktarda mayıs sineği ve taş sineği larvası buluyor. Bu bulgu en çok neyi gösterir?', 'Suyun temiz ve oksijence zengin olduğunu', ['Suyun ağır biçimde kirlendiğini', 'Derenin birkaç hafta içinde tamamen kurumak üzere olduğunu', 'Suyun tuzlu olduğunu'], 'Mayıs sineği ve taş sineği larvaları kirliliğe ve düşük oksijene çok duyarlıdır; bol bulunmaları temiz suyun biyolojik göstergesidir.'),
  ('Yengeç, karides ve ıstakozun böcekler gibi eklembacaklı olmasına karşın kabuklular grubunda toplanmasının gerekçesi hangisidir?', 'İki çift anten taşımaları ve çoğunun solungaçla solunum yapması', ['Kalkerli tek parça kabuk taşımaları', 'Hiç bacaklarının olmaması', 'İç iskelet taşımaları'], 'Kabuklular çoğunlukla sucul eklembacaklılardır; iki çift anten ve solungaç taşırlar, dış iskeletleri kalsiyum karbonatla sertleşmiştir.'),
  ('Yaz aylarında deniz kenarında bir denizanası ile temas eden kişinin derisinde yanma ve kızarıklık oluşmasının nedeni nedir?', 'Dokunaçlardaki yakıcı hücrelerin zehir salması', ['Denizanasının ısırması', 'Deniz suyunun yüksek tuzunun deriyi kimyasal olarak yakması', 'Denizanasının elektrik üretmesi'], 'Sölenterlerin knidosit adlı yakıcı hücreleri dokunulduğunda zehirli iplikçikler fırlatır; bu iplikçikler deriye batarak yanma ve kızarıklık yapar.'),
  ('Planarya gibi yassı solucanların bir parçadan bütün bir bireyi yeniden oluşturabilmesi hangi biyolojik özelliğin güçlü olduğunu gösterir?', 'Rejenerasyon', ['Fotosentez', 'Döl almaşı', 'Biyolojik birikim ve besin zinciri'], 'Planarya ikiye kesildiğinde her parça eksik kısımlarını yeniden oluşturabilir; bunu sağlayan bölünebilir kök hücrelere sahiptir.'),
  ('Köpek balığı ve vatoz gibi balıkları kemikli balıklardan ayıran özellik hangisidir?', 'İskeletlerinin kıkırdaktan oluşması', ['Solungaç taşımamaları', 'Pullarının bulunmaması', 'Kalplerinin memelilerdeki gibi dört odacıklı olması'], 'Kıkırdaklı balıklarda iskelet kıkırdaktır ve solungaç kapağı yoktur; kemikli balıklarda kemik iskelet ve solungaç kapağı bulunur.'),
  ('Kurbağaların yaşamlarının bir bölümünü suda bir bölümünü karada geçirmesi ve döllenmenin genellikle suda olması onları hangi sınıfa yerleştirir?', 'İki yaşamlılar', ['Sürüngenler', 'Kemikli balıklar', 'Memeliler'], 'İki yaşamlıların larvaları (iribaş) suda solungaçla solunum yapar; erginler akciğer ve nemli derileriyle solunum yapar. Yumurtaları kabuksuz olduğu için suya bağımlıdırlar.'),
  ('Kertenkelelerin sabah güneşlenmesi ve öğle sıcağında gölgeye çekilmesi hangi fizyolojik özellikleriyle ilişkilidir?', 'Vücut sıcaklıklarını dış ortamdan sağlamaları', ['Sabit vücut sıcaklığına sahip olmaları', 'Terleyerek serinlemeleri', 'Tüyler ve yağ tabakasıyla güçlü ısı yalıtımı yapmaları'], 'Sürüngenler ektotermdir; vücut ısılarını davranışla, güneşe çıkıp gölgeye girerek düzenler.'),
  ('Kuşların uçmaya uyumu olarak aşağıdaki özelliklerden hangisi beklenmez?', 'Kalın ve ağır, içi dolu kemikler', ['İçi boşluklu hafif kemikler', 'Hava keseleriyle desteklenen akciğerler', 'Göğüs kaslarının bağlandığı büyük göğüs kemiği'], 'Kuşların kemikleri hafif ve boşlukludur; hava keseleri tek yönlü verimli solunum sağlar, uçuş kasları büyük göğüs kemiği çıkıntısına bağlanır.'),
  ('Ornitorenk ve ekidne yumurtlayan memelilerdir. Bu hayvanları memeli sayma gerekçesi nedir?', 'Kıl taşımaları ve yavrularını sütle beslemeleri', ['Yumurtlamaları', 'Gaga taşımaları', 'Suda yaşayıp yüzebilmeleri ve perdeli ayakları'], 'Monotremler yumurtlar, ancak kılları ve süt bezleri olduğundan memelidir; yavrular annenin deri üzerindeki bölgelerden sızan sütle beslenir.'),
  ('Kanguru ve koala gibi keseli memelilerde yavrunun gelişimi diğer memelilerden nasıl farklıdır?', 'Çok küçük doğan yavru gelişimini annenin kesesinde tamamlar', ['Yavru yumurtadan çıkar ve hemen yürür', 'Yavru annenin içinde uzun süre plasentayla beslenir', 'Yavru doğumdan sonra hiçbir zaman sütle beslenmez'], 'Keselilerde gebelik kısadır ve yavru çok erken doğar; kesedeki meme başına tutunarak gelişimini sürdürür.'),
  ('Bir omurgalının tanımı şöyledir: pullu kuru deri, akciğer solunumu, kabuklu yumurta, değişken vücut sıcaklığı. Bu hayvan aşağıdakilerden hangisi olabilir?', 'Engerek yılanı', ['Semender', 'Yarasa', 'İmparator pengueni'], 'Pullu kuru deri, kabuklu yumurta ve ektotermi sürüngenlere özgüdür; semender iki yaşamlı, yarasa memeli, penguen kuştur.'),
  ('Balıkların kalbinin iki odacıklı olması dolaşımlarının hangi özelliğiyle ilgilidir?', 'Kanın kalpten bir kez geçerek solungaç ve vücudu dolaşması', ['Kanın hiç oksijen taşımaması', 'Kanın akciğere ve vücuda ayrı ayrı pompalanması', 'Kalbin hiç kasılmaması'], 'Balıklarda tek dolaşım vardır: kalp kanı solungaçlara pompalar, oradan kan doğrudan vücuda gider ve kalbe döner.'),
  ('Bir öğrenci \'Penguenler uçamadığı için kuş değildir\' diyor. Bu ifadenin değerlendirmesi hangisidir?', 'Yanlıştır; tüy, gaga ve kabuklu yumurta kuş olduklarını gösterir', ['Doğrudur; uçamayan kuş yoktur', 'Doğrudur; penguenler yüzgeçli deniz memelileridir', 'Yanlıştır; penguenler sürüngendir'], 'Kuş olmanın ölçütü uçma değil, tüy, gaga, kabuklu yumurta ve endotermi gibi özelliklerdir; deve kuşu ve kivi de uçamayan kuşlardır.'),
  ('Virüslerin canlılık özelliklerinden yalnız bazılarını gösterdiği söylenir. Aşağıdakilerden hangisi virüslerin canlılarla ortak özelliğidir?', 'Kalıtsal madde taşımaları ve mutasyona uğramaları', ['Kendi başlarına enerji üretmeleri', 'Hücre zarıyla çevrili olmaları', 'Konak hücre olmadan bağımsız olarak büyüyüp ikiye bölünmeleri'], 'Virüsler genetik madde taşır, konakta çoğalır ve mutasyonla değişip evrimleşebilir; ancak metabolizmaları yoktur ve kendi başlarına çoğalamazlar.'),
  ('Tütün mozaik virüsü, tütün yapraklarında alacalı lekelere yol açar. Bu örnek virüslerle ilgili hangi genellemeyi destekler?', 'Virüsler bitkileri de enfekte edebilir', ['Virüsler yalnız insanları enfekte eder', 'Virüsler fotosentez yapar', 'Virüsler yaprakta tohum ve spor oluşturarak çoğalır'], 'Tütün mozaik virüsü keşfedilen ilk virüstür ve bitki virüslerine örnektir; virüsler bakteri, bitki, hayvan ve mantar gibi her canlı grubunu enfekte edebilir.'),
  ('Virüslerin ışık mikroskobuyla görülemeyip elektron mikroskobuyla incelenmesinin nedeni nedir?', 'Boyutlarının ışık mikroskobunun çözünürlüğünden küçük olması', ['Virüslerin saydam ve kokusuz olması', 'Virüslerin yalnız gece görülebilmesi', 'Virüslerin mikroskop altında hiç hareket etmemesi ve ışığı soğurmaması'], 'Çoğu virüs birkaç on ile birkaç yüz nanometre boyundadır; ışık mikroskobunun çözünürlüğü yaklaşık 200 nanometre ile sınırlıdır.'),
  ('Bir bitki bilimci, viral hastalık taşıyan bir patates çeşidini temizlemek için bitkinin en uç meristem dokusundan doku kültürü yapıyor. Bu yöntemin işe yaramasının nedeni nedir?', 'Hızla bölünen uç meristemde virüs yoğunluğu çok düşüktür', ['Meristem hücreleri virüsleri sindirir', 'Meristemde virüsler fotosentezle ölür', 'Doku kültürü virüsleri bakteriye dönüştürür'], 'Uç meristemde iletim dokusu henüz gelişmediğinden virüs bu bölgeye yavaş ulaşır; buradan çoğaltılan bitkiler çoğunlukla virüssüz olur.'),
  ('Yaşlı bir ağaç gövdesinde koyu renkli merkezdeki öz odun (duramen) ile dıştaki açık renkli diri odun (albumen) arasındaki işlevsel fark nedir?', 'Su iletimi büyük ölçüde diri odunda yapılır', ['Öz odun floem özsuyunu taşır', 'Diri odun yalnız reçine depolar', 'Öz odun sürekli bölünen meristemdir'], 'Öz odun eski, tıkanmış ksilemden oluşur ve çoğunlukla destek sağlar; su ve mineral iletimi kambiyuma yakın genç diri odunda sürer.'),
  ('Şişe tıpası ve döşeme malzemesi olarak kullanılan doğal mantar, mantar meşesi ağacının hangi dokusundan elde edilir?', 'Kabuktaki mantar dokusu', ['Gövdedeki öz odun', 'Yapraktaki palizat dokusu', 'Kökteki endodermis'], 'Mantar meşesinin (Quercus suber) kalın mantar dokusu, mantar kambiyumunun ürettiği suberinli ölü hücrelerden oluşur; ağaca zarar vermeden belirli aralıklarla soyulabilir.'),
  ('Kaktüsün dikenleri değişikliğe uğramış yapraklarken, gülün dikenleri epidermis kökenli çıkıntılardır. Bu bilgiden hangi sonuç çıkarılır?', 'Benzer görünen yapılar farklı kökenlerden gelişebilir', ['Kaktüs ve gül aynı familyadadır', 'Gül dikeni fotosentez yapar', 'Kaktüs dikenleri tomurcuktan gelişir'], 'İkisi de koruma işlevi görse de kökenleri farklıdır; kaktüs dikeni yaprak, gül dikeni ise kabuktan kolayca koparılabilen yüzeysel bir çıkıntıdır.'),
  ('Atatürk çiçeği (Euphorbia pulcherrima) bitkisinin dikkat çeken kırmızı \'taç yaprakları\' aslında hangi yapılardır?', 'Renklenmiş brakteler', ['Gerçek taç yapraklar', 'Çanak yapraklar', 'Erkek organlar'], 'Atatürk çiçeğinde asıl çiçekler küçük ve gösterişsizdir; çevresindeki kırmızı yapılar, tozlayıcıları çeken renklenmiş yaprak benzeri brakteler (koruyucu yapraklar)dır.'),
  ('Soğanın yenen etli katmanları bitkinin hangi organının değişikliğe uğramış biçimidir?', 'Yaprak', ['Kök', 'Meyve', 'Çiçek'], 'Soğanın etli pulları besin depolayan değişmiş yaprak tabanlarıdır; bunlar tabandaki kısa, yassı bir gövdeye bağlıdır.'),
  ('Karanlıkta çimlendirilen fasulye fidelerinin uzun, ince ve soluk sarı olması hangi olayla adlandırılır ve bitkiye yararı nedir?', 'Etiyolasyon; ışığa ulaşmak için hızla uzama', ['Vernalizasyon; soğuğa dayanma', 'Gutasyon; su atma', 'Plazmoliz; su depolama'], 'Işıksız ortamda fide klorofil yapmaz ve enerjisini boy uzamasına harcar; böylece toprak altından ya da gölgeden ışığa ulaşma şansı artar.'),
  ('Fasulye ve bazı baklagillerin yapraklarının gece aşağı doğru kapanıp gündüz açılması hangi tür harekete örnektir?', 'Niktinasti', ['Gravitropizma', 'Kemotropizma', 'Tigmotropizma'], 'Gece-gündüz döngüsüne bağlı yönsüz yaprak hareketleri niktinastidir; yaprak tabanındaki hücrelerde turgor değişimiyle gerçekleşir.'),
  ('Çam ağaçlarının yaralandığında salgıladığı yapışkan reçinenin bitkiye sağladığı yarar nedir?', 'Yarayı kapatıp böcek ve mantarlara karşı korumak', ['Kökler için su depolamak', 'Tohumları rüzgârla taşımak', 'Polenleri çimlendirmek'], 'Reçine kanallarından akan reçine yarayı örter, böcekleri yapıştırıp uzaklaştırır ve antimikrobiyal maddeler içerir.'),
  ('Ayçiçeğinin büyük \'çiçeği\' aslında yüzlerce küçük çiçekten oluşur. Bu yapının adı ve tozlaşma açısından yararı nedir?', 'Kapitulum; tek ziyarette çok çiçeğin tozlaşması', ['Kozalak; rüzgârla tozlaşma', 'Yalancı meyve; tohum yayılması', 'Stolon; vejetatif üreme'], 'Papatyagillerde küçük çiçekler bir tabla üzerinde toplanarak kapitulum oluşturur; böcek tek seferde birçok çiçeği tozlaştırır.'),
  ('Böğürtlen ve ahududu tek bir çiçekteki çok sayıda dişi organdan gelişen küçük meyvelerin birleşmesiyle oluşur. Bu meyveler nasıl sınıflandırılır?', 'Toplu meyve', ['Basit kuru meyve', 'Yalancı meyve', 'Kapsül meyve'], 'Bir çiçeğin birden çok ayrı yumurtalığının her biri küçük bir meyvecik oluşturur; bunların bir arada bulunduğu yapıya toplu meyve denir.'),
  ('Muzların tohumsuz olması ve döllenme olmadan meyve oluşmasına ne ad verilir?', 'Partenokarpi', ['Vernalizasyon', 'Stratifikasyon', 'Gutasyon'], 'Partenokarpide döllenme olmaksızın yumurtalık meyveye dönüşür; kültür muzlarında bu yüzden gelişmiş tohum bulunmaz ve çoğaltma vejetatif yolla yapılır.'),
  ('Fasulye ve bezelye meyvesinin olgunlaşınca iki yarısının kuruyup birden açılarak tohumları fırlatması hangi yayılma yoludur?', 'Kendi kendine (mekanik) yayılma', ['Rüzgârla yayılma', 'Hayvanlarla yayılma', 'Suyla yayılma'], 'Bazı baklagiller ve gelincik benzeri bitkilerde kuruyan meyve çeperindeki gerilim aniden boşalır ve tohumlar fırlatılarak yayılır.'),
  ('Çöl bölgelerinde yağmurdan sonra birkaç hafta içinde çimlenip çiçek açan ve tohum bırakarak kuruyan tek yıllık bitkilerin stratejisi nasıl yorumlanır?', 'Kuraklığı dayanıklı tohum evresinde geçirirler', ['Kuraklığı derin kökleriyle karşılarlar', 'Kuraklıkta yapraklarını su ile doldururlar', 'Kuraklık sırasında hızla büyürler'], 'Bu efemer bitkiler kısa süreli nemli dönemi değerlendirir; kurak dönemi kuruma dayanıklı tohumlar olarak toprakta bekleyerek geçirir.'),
  ('Hidroponik tarımda bitkiler toprak olmadan yetiştirilir. Bu yöntemde bitkinin gereksinim duyduğu mineraller nasıl sağlanır?', 'Kökleri besin çözeltisine daldırarak', ['Yapraklara toprak serperek', 'Bitkiyi tamamen karanlıkta tutarak', 'Gövdeye kum aşılayarak'], 'Hidroponikte mineraller suda çözünmüş besin çözeltisiyle doğrudan köklere verilir; köklerin havalandırılması da gereklidir.'),
  ('Tuzlu suyla sulanan bir bitkinin, toprakta su olmasına karşın solmaya başlaması nasıl açıklanır?', 'Toprak çözeltisi hipertonik olduğundan kök su alamaz', ['Tuz yapraklarda klorofili artırır', 'Tuz köklere fazla su pompalar', 'Tuz bitkinin stomalarını açık tutar'], 'Toprak suyu çok tuzlu olduğunda su potansiyeli kök hücrelerinden düşük olur; su köke giremez, hatta kökten dışarı çıkabilir ve bitki fizyolojik kuraklık yaşar.'),
  ('Bir araştırmacı yulaf fidesinin uç kısmını kesip yerine oksin emdirilmiş bir agar bloğu koyuyor ve fidenin büyümeye devam ettiğini görüyor. Bu deney neyi gösterir?', 'Büyümeyi uyaran madde uçtan aşağı taşınan bir kimyasaldır', ['Fide ucunun hiçbir işlevi yoktur', 'Agar bloğu fotosentez yapar', 'Büyümeyi yalnız ışık doğrudan sağlar'], 'Fide ucunun yerini oksinli agar alabiliyorsa, uçta üretilip aşağı taşınan kimyasal bir haberci büyümeyi denetliyor demektir; bu deneyler oksinin keşfine yol açmıştır.'),
  ('Bir balık türü yalnız 12-16 °C arasındaki sularda yaşayabilirken başka bir tür 2-30 °C arasında yaşayabiliyor. Bu iki tür hakkında hangi çıkarım doğrudur?', 'İkinci türün sıcaklık tolerans aralığı daha geniştir', ['Birinci tür daha geniş alana yayılır', 'İki türün toleransı aynıdır', 'Birinci tür sıcaklık değişimlerine daha dayanıklıdır'], 'Tolerans aralığı geniş olan türler (ör. 2-30 °C) değişken koşullara daha iyi uyum sağlar ve genellikle daha geniş alanlara yayılır.'),
  ('Ayıların ve kirpilerin kışı uyuyarak geçirmesinin enerji açısından temel yararı nedir?', 'Besin kıtlığında metabolizmayı düşürerek enerji tasarrufu', ['Kış boyunca daha çok avlanma', 'Vücut ısısını artırarak donmayı önleme', 'Fotosentez yaparak besin üretme'], 'Kışın besin bulmak zordur; metabolizma yavaşlar, vücut ısısı ve kalp atışı düşer, hayvan depoladığı yağla yaşamını sürdürür.'),
  ('Bazı yaban arısı türleri yumurtalarını tırtılların içine bırakır; gelişen larvalar tırtılı içten yiyerek sonunda öldürür. Bu canlılara ne ad verilir ve tarımda nasıl kullanılır?', 'Parazitoit; zararlıların biyolojik mücadelesinde', ['Ayrıştırıcı; gübre yapımında', 'Kommensal; tozlaşmada', 'Üretici; yeşil gübrelemede'], 'Parazitoitler konakçılarını sonunda öldürdükleri için klasik parazitlerden ayrılır; tarım zararlılarını azaltmak amacıyla biyolojik mücadelede yararlanılır.'),
  ('Bir seracı yaprak bitlerine karşı kimyasal ilaç yerine uğur böceği salıyor. Bu yöntemin ekolojik üstünlüğü nedir?', 'Kalıntı bırakmadan avcı-av ilişkisiyle zararlıyı azaltması', ['Uğur böceklerinin bitkileri gübrelemesi', 'Yaprak bitlerinin uğur böceklerine dönüşmesi', 'Seradaki tüm böceklerin yok olması'], 'Uğur böcekleri yaprak bitlerinin doğal avcısıdır; biyolojik mücadele ilaç kalıntısını ve faydalı türlerin zarar görmesini azaltır.'),
  ('Bir adanın tür sayısının genellikle adanın büyüklüğü ve anakaraya uzaklığıyla ilişkili olduğu bilinir. Aşağıdaki adalardan hangisinde en fazla tür beklenir?', 'Büyük ve anakaraya yakın ada', ['Küçük ve anakaraya uzak ada', 'Küçük ve anakaraya yakın ada', 'Büyük ve anakaraya çok uzak ada'], 'Ada biyocoğrafyası kuramına göre büyük adalar daha çok habitat sunar ve yok olma hızı düşüktür; yakın adalara göç daha kolaydır.'),
  ('1980\'lerde gemilerin balast sularıyla Karadeniz\'e taşınan ve zooplankton ile balık yumurtalarını tüketerek hamsi avının çökmesine katkıda bulunan istilacı canlı hangisidir?', 'Mnemiopsis leidyi', ['Caretta caretta', 'Aslan balığı', 'Zebra midyesi'], 'Amerika kökenli taraklı medüz Mnemiopsis leidyi Karadeniz\'de doğal düşmanı olmadan çoğalmış, besin ağını bozmuştur; aşırı avcılık ve ötrofikasyonla birlikte hamsi stokları çökmüştür.'),
  ('1950\'lerde Japonya\'nın Minamata körfezinde fabrika atıklarıyla denize karışıp balıklarda birikerek insanlarda ağır sinir sistemi hastalığına yol açan madde hangisidir?', 'Cıva bileşikleri', ['Kurşun', 'Kükürt dioksit', 'Karbon monoksit'], 'Fabrikadan atılan metil cıva besin zincirinde birikmiş; bu balıkları yiyen insanlarda Minamata hastalığı olarak bilinen nörolojik bozukluk görülmüştür.'),
  ('Orta Asya\'daki Aral Gölü\'nün 20. yüzyılın ikinci yarısında büyük ölçüde küçülmesinin başlıca nedeni nedir?', 'Besleyen nehirlerin suyunun sulamaya aktarılması', ['Göle aşırı miktarda yağmur yağması', 'Gölde dev volkanik patlama olması', 'Gölün donup buzul olması'], 'Amuderya ve Siriderya nehirlerinin suyu pamuk sulamasına yönlendirilince göl büyük ölçüde kurumuş, tuzluluk artmış ve balıkçılık çökmüştür.'),
  ('Kıyıya yakın yapılaşmadaki yoğun yapay ışıkların, yeni yumurtadan çıkan deniz kaplumbağası yavrularına zararı nedir?', 'Yavruların denize değil ışığa doğru yönelmesi', ['Yavruların kabuklarının sertleşmesi', 'Yavruların hızlı büyümesi', 'Yumurtaların daha çok olması'], 'Yavrular deniz ufkunun parlaklığına yönelerek denizi bulur; yapay ışıklar onları karaya çeker, yavrular kuruyarak ya da avlanarak ölür.'),
  ('Bir araştırmacı, uzun yıllık kayıtlarda bir bölgedeki bademlerin her on yılda birkaç gün daha erken çiçeklendiğini buluyor. Bu tür mevsimsel olayların zamanlamasını inceleyen bilim dalı hangisidir?', 'Fenoloji', ['Paleontoloji', 'Sitoloji', 'Histoloji'], 'Fenoloji çiçeklenme, göç ve yumurtlama gibi biyolojik olayların mevsimsel zamanlamasını inceler; bu kayıtlar iklim değişikliğinin önemli göstergeleridir.'),
  ('Eğimli arazilerde tarım yapan bir köyde yağışlarla toprak kaybı artıyor. En uygun önlem hangisidir?', 'Eğime dik teraslar yapmak ve bitki örtüsünü korumak', ['Eğim yönünde derin sürüm yapmak', 'Tüm ağaçları kesip alanı açmak', 'Toprağı her yıl yakmak'], 'Teraslar suyun akış hızını keser, bitki kökleri toprağı tutar; eğim yönünde sürüm ise erozyonu artırır.'),
  ('Leylekler ve yırtıcı kuşlar sonbahar göçünde İstanbul Boğazı gibi dar kara geçitleri kullanır ve uzun deniz geçişlerinden kaçınır. Bunun en iyi açıklaması nedir?', 'Kanat çırpmadan süzülmek için karada oluşan sıcak hava akımlarına gereksinim duymaları', ['Denizin üzerinde hiç rüzgâr esmemesi', 'Deniz üzerinde yönlerini kaybetmeleri', 'Boğazda bol balık avlayabilmeleri'], 'Süzülerek göç eden iri kuşlar, karada güneşle ısınan havanın oluşturduğu yükselen akımları (termikleri) kullanır; deniz üzerinde bu akımlar zayıftır.'),
  ('Bir petrol sızıntısının temizlenmesinde, hidrokarbonları parçalayabilen bakterilerin çoğalmasının desteklenmesi hangi yöntemin örneğidir?', 'Biyoremediasyon', ['Ötrofikasyon', 'Biyolojik büyütme', 'Vernalizasyon'], 'Biyoremediasyonda mikroorganizmalar kirleticileri daha az zararlı maddelere parçalar; petrol ve bazı tarım ilaçlarının temizlenmesinde kullanılır.'),
  ('Mikrobiyoloji laboratuvarlarında besi ortamını katılaştırmak için kullanılan agar hangi canlı grubundan elde edilir?', 'Kırmızı algler', ['Kahverengi mantarlar', 'Siyanobakteriler', 'Yeşil karayosunları'], 'Agar, kırmızı alglerin çeperlerinden elde edilen bir polisakkarittir; ayrıca gıda sanayisinde jöle yapıcı olarak kullanılır.'),
  ('Diyatomelerin ölü kabuklarının birikmesiyle oluşan diyatome toprağının filtre ve aşındırıcı olarak kullanılmasını sağlayan özellik nedir?', 'Kabuklarının silisten yapılmış olması', ['Kabuklarının selülozdan yapılmış olması', 'Kabuklarının kitinden yapılmış olması', 'Kabuklarının demirden yapılmış olması'], 'Diyatomeler camsı silis (SiO2) kabuk yapar; kabukların ince gözenekli yapısı süzme işlerinde, sertliği ise aşındırıcı olarak kullanılmasını sağlar.'),
  ('Orta Çağ Avrupa\'sında kangren, sanrı ve kasılmalarla seyreden toplu zehirlenmelere, çavdar başaklarında gelişen ve alkaloit üreten bir mantar yol açmıştır. Bu mantar hangisidir?', 'Çavdar mahmuzu (Claviceps purpurea)', ['Ekmek mayası (Saccharomyces)', 'Penicillium notatum', 'Kültür mantarı (Agaricus)'], 'Claviceps purpurea\'nın oluşturduğu sert yapılar unla birlikte öğütüldüğünde ergot alkaloitleri ergotizm denen zehirlenmeye yol açmıştır.'),
  ('Maya, tek hücreli olmasına karşın mantarlar aleminde sınıflandırılır. Bunun en geçerli gerekçesi hangisidir?', 'Kitinli çepere sahip, besinini emerek alan bir ökaryot olması', ['Prokaryot olması', 'Fotosentez yapması', 'Tüm mantarların tek hücreli olması'], 'Hücre sayısı tek başına alemi belirlemez; maya hücre çeperi, beslenme biçimi ve moleküler özellikleriyle mantarlara uyar.'),
  ('Balıkların vücudunun iki yanında bulunan yan çizgi organı hangi uyaranı algılar?', 'Sudaki basınç dalgaları ve titreşimler', ['Güneş ışığının rengi', 'Havadaki koku molekülleri', 'Manyetik kutupların yeri'], 'Yan çizgi organı sudaki hareket ve titreşimleri algılar; balıklar bununla av, avcı ve engelleri bulanık suda bile fark eder, sürü içinde uyumlu yüzer.'),
  ('Yarasaların karanlıkta yüksek frekanslı sesler çıkarıp yankılarını dinleyerek av bulmasına ne ad verilir?', 'Ekolokasyon', ['Fotoperiyodizm', 'Biyolüminesans', 'Kemotaksis'], 'Ekolokasyonda yarasa ses dalgaları yayar ve geri dönen yankılardan nesnelerin uzaklığını, büyüklüğünü ve hareketini çıkarır; yunuslar da bu yöntemi kullanır.'),
  ('Bir hayvan ön-arka ve sağ-sol ayrımı olan iki yanlı simetriye sahipse genellikle başında duyu organları ve sinir hücreleri yoğunlaşmıştır. Bu eğilime ne ad verilir?', 'Sefalizasyon', ['Rejenerasyon', 'Metamorfoz', 'Hibernasyon'], 'İki yanlı simetrili hayvanlar belirli bir yöne doğru hareket eder; önde karşılaşılan uyaranları algılamak için duyu organları ve beyin baş bölgesinde toplanır.'),
  ('Kuşlarla tozlaşan çiçekler çoğunlukla kırmızı renkli, tüp biçimli ve bol nektarlı olur, ancak kokuları zayıftır. Kokunun zayıf olması nasıl açıklanır?', 'Kuşların koku duyusu görmeye göre zayıftır', ['Kuşlar kokulu çiçeklerden korkar', 'Koku polenin üremesini engeller', 'Kırmızı renk kokuyu yok eder'], 'Kuşlar çiçekleri büyük ölçüde görme ile bulur; bu yüzden enerji, renk ve nektara harcanır. Böcekle tozlaşan çiçeklerde ise koku önemli bir çekicidir.'),
  ('Gece açan, beyaz ya da soluk renkli, güçlü kokulu ve bol nektarlı iri çiçekler en olası olarak hangi canlılarla tozlaşır?', 'Yarasalar ve gece kelebekleri', ['Gündüz uçan kuşlar', 'Rüzgâr', 'Su akıntıları'], 'Gece etkin tozlayıcılar karanlıkta rengi değil kokuyu ve açık renkli yüzeyi algılar; bu çiçek özellikleri onlara yönelik uyumlardır.'),
  ('Tipik bir kapalı tohumlu bitkinin olgun embriyo kesesinde kaç çekirdek bulunur?', '8', ['4', '7', '16'], 'Megaspor üç kez mitoz geçirerek 8 çekirdek oluşturur; bunlar 7 hücreye dağılır: yumurta, iki sinerjit, üç antipot ve iki kutup çekirdekli merkez hücre.'),
  ('Bir asma dalının ana bitkiden ayrılmadan toprağa gömülüp köklendikten sonra kesilerek yeni bitki elde edilmesi hangi yöntemdir?', 'Daldırma', ['Aşılama', 'Çelikle üretme', 'Doku kültürü'], 'Daldırmada dal ana bitkiden beslenirken toprakta kök oluşturur; köklenince ana bitkiden ayrılır.'),
  ('Yer elması ve tatlı patateste besin depolayan yapılardan biri gövde, diğeri kök kökenlidir. Aşağıdakilerden hangisi kök kökenli depo organlarının ayırt edici özelliğidir?', 'Boğum ve tomurcuk taşımamaları', ['Nişasta depolamaları', 'Toprak altında bulunmaları', 'Su içermeleri'], 'Tatlı patates bir yumru köktür; üzerinde boğum ve göz (tomurcuk) bulunmaz. Patates ve yer elması ise tomurcuklu gövde yumrularıdır.'),
  ('Bir bitkinin fotosentez hızının solunum hızına eşit olduğu ışık şiddetine ışık kompansasyon noktası denir. Bu noktanın altındaki ışıkta uzun süre kalan bitkide ne olur?', 'Depoladığı besini tüketerek zayıflar', ['Hızla büyüyüp çiçeklenir', 'Fotosentez yapmadan oksijen üretir', 'Besin depoları sürekli artar'], 'Kompansasyon noktasının altında solunum fotosentezden fazladır; bitki net organik madde kaybeder ve uzun sürede ölebilir. Gölge bitkilerinde bu nokta daha düşüktür.'),
  ('Kara bitkilerinin çoğunda stomaların yaprağın alt yüzeyinde daha yoğun bulunması hangi yararı sağlar?', 'Doğrudan güneş almayan yüzeyde su kaybının azalması', ['Fotosentezin yaprağın altında yapılması', 'Kök basıncının artması', 'Polenlerin yaprakta tutulması'], 'Alt yüzey daha serin ve gölgededir; buradaki stomalardan buharlaşma daha az olur. Yüzen su bitkilerinde ise stomalar üst yüzeydedir.'),
  ('Bazı çam türlerinin kozalaklarının ancak yangın sıcağıyla açılarak tohum bırakması ekolojik olarak nasıl yorumlanır?', 'Yangın sonrası açılan alanda fidelerin hızla yerleşmesi', ['Yangını başlatmak için evrimleşmiş olmaları', 'Tohumların ateşte pişip ölmesi', 'Ormanın hiç yenilenmemesi'], 'Yangın rakip bitkileri ortadan kaldırır, ışık ve küllerle mineral sağlar; bu anda bırakılan tohumlar uygun koşullarda çimlenir. Bu, yangına uyumlu ekosistemlerin özelliğidir.'),
  ('Bir meradaki hayvan sayısı uzun yıllar taşıma kapasitesinin üzerinde tutulursa bölgede en olası uzun vadeli sonuç hangisidir?', 'Bitki örtüsünün bozulması ve çölleşme riski', ['Toprağın daha verimli hâle gelmesi', 'Tür çeşitliliğinin sürekli artması', 'Yağışların düzenli olarak artması'], 'Aşırı otlatma bitki örtüsünü yok eder, toprak açıkta kalır ve rüzgâr-su erozyonuyla kaybolur; kurak bölgelerde bu süreç çölleşmeye yol açabilir.'),
  ('İki ormanda da 10 ağaç türü vardır. Birinci ormanda ağaçların %90\'ı tek türdür, ikincisinde her tür yaklaşık eşit sayıdadır. Çeşitlilik açısından doğru değerlendirme hangisidir?', 'Tür zenginliği aynı, ikinci ormanın tür eşitliği daha yüksektir', ['Birinci ormanın çeşitliliği daha yüksektir', 'İki ormanın her açıdan çeşitliliği aynıdır', 'İkinci ormanda tür sayısı daha fazladır'], 'Tür zenginliği tür sayısıdır ve ikisinde de 10\'dur. Bireylerin türlere dengeli dağılımı (eşitlik) ikinci ormanda yüksektir; bu da genel çeşitliliği artırır.'),
  ('Tozlayıcı böceklerin korunmasının ekonomik açıdan da önemli sayılmasının en doğrudan nedeni nedir?', 'Birçok besin bitkisinin verimi tozlaşmaya bağlıdır', ['Böceklerin topraktaki tuzu azaltması', 'Böceklerin fosil yakıt üretmesi', 'Böceklerin yağmur yağdırması'], 'Meyve, sebze ve yağlı tohumların önemli bir bölümü hayvanlarla tozlaşır; tozlayıcı kaybı ürün miktarını ve kalitesini düşürür.'),
  ('1952 Aralık\'ında Londra\'da birkaç gün süren yoğun sis olayında binlerce kişinin ölümüne yol açan kirliliğin başlıca kaynağı nedir?', 'Kömür yakılmasından çıkan is ve kükürt dioksit', ['Nükleer santral sızıntısı', 'Okyanuslardan gelen tuz', 'Bitki polenleri'], 'Soğuk hava ve sıcaklık terselmesi, ev ve fabrikalarda yakılan kömürün dumanını kente hapsetti; is ve kükürt dioksit solunum yolu hastalıklarından çok sayıda ölüme yol açtı.'),
  ('Ilıman bölgelerdeki bir dağın kuzeye bakan yamacının güneye bakan yamaca göre daha nemli ve serin olması bitki örtüsünü nasıl etkiler?', 'Kuzey yamaçta nem seven türler daha yaygın olur', ['Kuzey yamaçta yalnız kaktüsler yetişir', 'İki yamaçta bitki örtüsü tamamen aynıdır', 'Güney yamaçta hiç bitki yetişmez'], 'Kuzey yarımkürede kuzey yamaçlar daha az doğrudan güneş alır; bu mikroklima farkı nem ve gölge seven türlerin bu yamaçlarda yoğunlaşmasına yol açar.'),
  ('Aşağıdaki özelliklerden hangisi bitkiler aleminin tüm üyeleri için ortak değildir?', 'Çiçek ve tohum oluşturma', ['Ökaryot hücre yapısı', 'Selülozlu hücre çeperi', 'Çok hücreli embriyo evresi'], 'Karayosunları ve eğreltiler de bitkidir, ancak çiçek ve tohum oluşturmaz; ökaryot yapı, selülozlu çeper ve çok hücreli embriyo tüm kara bitkilerinde bulunur.'),
  ('Kelebeklerin dokunulduğunda parmağa toz gibi bulaşan kanat örtüsü hangi takımın adını açıklar?', 'Pul kanatlılar', ['Zar kanatlılar', 'Kınkanatlılar', 'Düz kanatlılar'], 'Kelebek ve güvelerin (Lepidoptera) kanatları renkli küçük pullarla kaplıdır; takımın adı bu pullardan gelir.'),
  ('Türkiye\'de özellikle ilkbahar ve yaz aylarında görülen Kırım-Kongo kanamalı ateşi hastalığının etkeni ve insana bulaşmasında en önemli vektör hangi seçenekte doğru verilmiştir?', 'Bir virüs; kene', ['Bir bakteri; sivrisinek', 'Bir protist; çeçe sineği', 'Bir mantar; pire'], 'KKKA bir virüs hastalığıdır ve başlıca Hyalomma cinsi kenelerin ısırmasıyla bulaşır; enfekte hayvan kanı ve dokularıyla temas da bulaşmaya yol açabilir.'),
  ('Örümceklerin ağ yapımında kullandığı ipeğin bir protein olması ve karın bölgesindeki bezlerden salgılanması, örümceklerin ekosistemdeki rolüyle nasıl ilişkilidir?', 'Ağ, böcekleri yakalayan etkin bir avlanma aracıdır', ['Ağ fotosentez yaparak besin üretir', 'Ağ topraktaki suyu toplar', 'Ağ yalnız yumurtaları ısıtmak için kullanılır'], 'Örümcekler etçildir; ağlarıyla çok sayıda böcek yakalayarak böcek popülasyonlarını denetleyen önemli avcılardır.'),
  ('Kaplumbağaların kabuğu ile diğer sürüngenlerin iskeleti karşılaştırıldığında kaplumbağa kabuğuna ilişkin doğru ifade hangisidir?', 'Kabuk, kaburgalar ve omurgayla kaynaşmış kemik yapıdır', ['Kabuk dışarıdan takılıp çıkarılabilen bir yapıdır', 'Kabuk kitinden oluşan bir dış iskelettir', 'Kabuk yalnız deriden oluşur ve kemik içermez'], 'Kaplumbağa kabuğunun sırt kısmı kaburgalar ve omurlarla kaynaşmıştır; bu nedenle kaplumbağa kabuğundan çıkamaz.'),
  ('Kuşların dişlerinin olmamasına karşın sert tohumları sindirebilmesinde rol oynayan, kaslı ve içinde çoğunlukla yutulmuş küçük taşlar bulunan sindirim organı hangisidir?', 'Taşlık', ['Kursak', 'Yüzme kesesi', 'Hava kesesi'], 'Taşlık kaslı bir mide bölümüdür; içindeki küçük taşlar ve kasılmalar besini öğütür. Kursak ise besinin geçici depolandığı yerdir.'),
  ('Köpek balıklarının bulanık suda veya kuma gömülü avları bulabilmesinde etkili olan özel duyu organları hangi uyaranı algılar?', 'Canlıların oluşturduğu zayıf elektrik alanlarını', ['Güneşin morötesi ışınlarını', 'Havadaki koku moleküllerini', 'Yer çekimindeki değişimleri'], 'Köpek balıklarının burun çevresindeki Lorenzini ampulleri, avların kas ve sinir etkinliğinden kaynaklanan çok zayıf elektrik alanlarını algılar.'),
  ('Deli dana hastalığı (BSE) gibi hastalıklara, nükleik asit içermeyen ve yanlış katlanmış bir proteinden oluşan enfeksiyon etkenleri yol açar. Bu etkenlere ne ad verilir?', 'Prion', ['Viroid', 'Bakteriyofaj', 'Plazmit'], 'Prionlar normal proteinlerin yanlış katlanmasını tetikleyerek çoğalır; nükleik asitleri yoktur ve sinir dokusunda birikerek hasar yapar.'),
  ('Bir bitki virüsünün bir bitkiden diğerine yayılmasında yaprak bitlerinin rol oynaması bu böceklerin hangi rolünü gösterir?', 'Vektör (taşıyıcı) rolü', ['Ayrıştırıcı rolü', 'Üretici rolü', 'Tozlayıcı rolü'], 'Floemle beslenen yaprak bitleri hortumlarıyla virüsleri enfekte bitkiden sağlam bitkiye taşıyarak vektör görevi görür.'),
  ('Kültür mantarı olarak yetiştirilen şapkalı mantarın (Agaricus bisporus) yenen kısmı mantarın hangi yapısıdır?', 'Spor üreten üreme yapısı', ['Toprak altındaki kökü', 'Fotosentez yapan yaprağı', 'Tohum taşıyan meyvesi'], 'Şapkalı mantar, toprak altındaki misel ağının oluşturduğu üreme yapısıdır; şapkanın altındaki lamellerde sporlar üretilir. Mantarların kökü ve tohumu yoktur.'),
  ('Bir öğrenci \'Balina ile köpek balığı aynı sınıftadır, çünkü ikisi de denizde yaşar ve yüzgeçleri vardır\' diyor. Bu akıl yürütmedeki hata nedir?', 'Ortak yaşam ortamı ve analog yapılar akrabalık ölçütü değildir', ['Balinaların yüzgeci yoktur', 'Köpek balıkları karada yaşar', 'Sınıflandırma yalnız renge göre yapılır'], 'Balina memeli, köpek balığı kıkırdaklı balıktır; benzer yüzgeç biçimi benzer ortama uyumun sonucudur. Sınıflandırmada homolog yapılar ve genetik benzerlik esas alınır.'),
  ('\'Protista\' terimini önererek tek hücreli canlılar için bitki ve hayvanlardan ayrı bir grup oluşturulmasına öncülük eden 19. yüzyıl bilim insanı kimdir?', 'Ernst Haeckel', ['Robert Hooke', 'Louis Pasteur', 'Gregor Mendel'], 'Ernst Haeckel 1866\'da mikroskobik canlıları bitki ve hayvanlardan ayırmak için Protista grubunu önermiştir.'),
  ('Akciğerli balıkların kurak mevsimde çamura gömülüp hava soluyarak yaşayabilmesi, sınıflandırmada bu balıkların hangi grupla ilişkisi açısından ilgi çekicidir?', 'Kara omurgalılarına yakın akraba olmaları', ['Kıkırdaklı balıklardan türemiş olmaları', 'Omurgasız olmaları', 'Sürüngenlerden türemiş olmaları'], 'Akciğerli balıklar etli yüzgeçli kemikli balıklardır; anatomik ve moleküler veriler onları iki yaşamlılar ve diğer kara omurgalılarına en yakın yaşayan balıklar arasında gösterir.'),
  ('Bir yetiştirici, akvaryumundaki tropik balıkların ısıtıcı bozulduktan sonra durgunlaşıp beslenmeyi bıraktığını görüyor. Bu durumun en iyi açıklaması hangisidir?', 'Su sıcaklığının türün tolerans aralığının altına düşmesi', ['Suyun oksijeninin aşırı artması', 'Akvaryum ışığının renginin değişmesi', 'Balıkların kış uykusuna hazırlanması'], 'Her türün belirli bir sıcaklık tolerans aralığı vardır; tropik balıklar için düşük sıcaklık metabolizmayı yavaşlatır ve uzarsa ölüme yol açabilir.'),
  ('Bir mağara ekosisteminde güneş ışığı yoktur ve fotosentez yapan canlı bulunmaz. Bu ekosistemin enerji kaynağı çoğunlukla nedir?', 'Dışarıdan taşınan organik madde', ['Mağara duvarlarının ısısı', 'Mağaradaki suyun buharlaşması', 'Mağara canlılarının fotosentezi'], 'Mağaralarda besin genellikle yarasa dışkısı (guano), suyla taşınan yapraklar ve giren hayvanlar gibi dış kaynaklardan gelir; bazı mağaralarda kemosentetik bakteriler de katkı sağlar.'),
  ('Bir türün kuramsal olarak kullanabileceği tüm koşul ve kaynakları kapsayan niş ile rakipler nedeniyle gerçekte kullandığı niş arasındaki ayrım hangi kavramlarla ifade edilir?', 'Temel niş ve gerçekleşmiş niş', ['Birincil ve ikincil süksesyon', 'Brüt ve net üretim', 'Biyotik ve abiyotik etmen'], 'Temel niş, rekabet olmadan kullanılabilecek alandır; gerçekleşmiş niş ise rekabet ve avcılık gibi etkileşimler sonucunda daralmış kullanım alanıdır.'),
  ('Kesme çiçeklerin vazoda daha uzun süre dayanması için çiçekçilerin etilen etkisini engelleyen maddeler kullanması hangi amaca yöneliktir?', 'Yaşlanma ve solmayı geciktirmek', ['Çiçeklerin daha hızlı açılmasını sağlamak', 'Çiçeklerin kök salmasını sağlamak', 'Çiçeklerin renk değiştirmesini sağlamak'], 'Etilen çiçeklerde yaşlanmayı, taç yaprak dökümünü ve solmayı hızlandırır; etkisi engellenirse çiçekler daha uzun süre taze kalır.'),
  ('Doğal bir ormanın tek tür ağaçtan oluşan bir plantasyonla değiştirilmesi, toplam ağaç sayısı aynı kalsa bile neden kuş çeşitliliğini azaltır?', 'Farklı kuşların gereksinim duyduğu habitat çeşitliliği azalır', ['Ağaçların fotosentezi tamamen durur', 'Kuşların uçma yeteneği kaybolur', 'Toprak azotu sıfıra iner'], 'Farklı ağaç türleri, yaşlar ve katmanlar çeşitli besin ve yuva alanları sunar; tek tip plantasyonda bu nişler ortadan kalktığı için birçok kuş türü barınamaz.'),
  ('Bir göl kıyısından ortasına doğru gidildiğinde önce sazlık ve kamışlar, sonra yüzen yapraklı nilüferler, en derinde ise yalnız plankton görülüyor. Bu sıralamayı en çok hangi etmen belirler?', 'Su derinliği ve ışığın dibe ulaşması', ['Suyun tuz oranının artması', 'Gölün rengi', 'Rüzgârın yönü'], 'Köklü bitkiler ancak ışığın dibe ulaştığı sığ kesimlerde yaşayabilir; derin kesimlerde yalnız yüzeyde sürüklenen fitoplankton fotosentez yapabilir.'),
];
